const pipeline_rendering_create_info_stype: i32 = 1_000_044_002;
const pipeline_robustness_create_info_stype: i32 = 1_000_068_000;
const attachment_store_op_none: i32 = 1_000_301_000;
const attachment_load_op_none: i32 = 1_000_400_000;
fn validAttachmentLoadOp(op: i32) bool {
    return op == 0 or op == 1 or op == 2 or op == attachment_load_op_none;
}
fn validAttachmentStoreOp(op: i32) bool {
    return op == 0 or op == 1 or op == attachment_store_op_none;
}

fn pipelineRobustnessNodeValid(item: *const anyopaque) bool {
    const info: *const PipelineRobustnessCreateInfo = @ptrCast(@alignCast(item));
    // The optional pipelineRobustness feature is not advertised.  The
    // Vulkan default behavior is nevertheless ABI-valid and has no
    // execution effect, so accept only the all-device-default form.
    return info.storage_buffers == 0 and info.uniform_buffers == 0 and info.vertex_inputs == 0 and info.images == 0;
}

fn pipelineRobustnessCreateInfoValid(raw: ?*const anyopaque) bool {
    var next = raw;
    var depth: usize = 0;
    var seen = false;
    while (next) |item| {
        if (depth == 16) return false;
        const header: *const ChainHeader = @ptrCast(@alignCast(item));
        if (header.s_type != pipeline_robustness_create_info_stype or seen) return false;
        if (!pipelineRobustnessNodeValid(item)) return false;
        seen = true;
        next = header.p_next;
        depth += 1;
    }
    return true;
}

// VK_KHR_maintenance5 promotes VkPipelineCreateFlags2CreateInfo into the
// core 1.4 pipeline-create pNext chain.  The CPU backend has one supported
// flag (dispatch base); validate the chain before any pipeline state or cache
// bytes are published so unsupported/high bits remain failure-atomic.
fn pipelineCreateFlags2(raw: ?*const anyopaque, legacy: u32, allow_dispatch_base: bool) ?u32 {
    if (raw == null) {
        if (!allow_dispatch_base and legacy != 0) return null;
        if (legacy & ~pipeline_create_dispatch_base_bit != 0) return null;
        return legacy;
    }
    var next = raw;
    var depth: usize = 0;
    var effective: u32 = legacy;
    var seen_flags2 = false;
    var seen_robustness = false;
    while (next) |item| {
        if (depth == 16) return null;
        const header: *const ChainHeader = @ptrCast(@alignCast(item));
        switch (header.s_type) {
            pipeline_create_flags2_stype => {
                if (seen_flags2) return null;
                const flags2: *const PipelineCreateFlags2CreateInfo = @ptrCast(@alignCast(item));
                // The promoted flags replace the legacy field (including when
                // the legacy field contains a supported dispatch-base bit), as
                // specified by the Vulkan 1.4 promotion rules.
                if (flags2.p_next != null) return null;
                if (flags2.flags & ~@as(u64, pipeline_create_dispatch_base_bit) != 0) return null;
                effective = @truncate(flags2.flags);
                seen_flags2 = true;
            },
            pipeline_robustness_create_info_stype => {
                if (seen_robustness or !pipelineRobustnessNodeValid(item)) return null;
                seen_robustness = true;
            },
            else => return null,
        }
        next = header.p_next;
        depth += 1;
    }
    if (!allow_dispatch_base and effective != 0) return null;
    return effective;
}

const PipelineRenderingState = struct {
    view_mask: u32,
    color_format: i32,
    depth_format: i32,
    stencil_format: i32,
};
const GraphicsPipelinePNextState = struct {
    flags: u32,
    rendering: ?PipelineRenderingState = null,
};

// Graphics pipeline creation accepts the promoted flags2 node together with
// VkPipelineRenderingCreateInfo.  Keep this parser bounded and failure-atomic:
// unknown, duplicate, malformed, or over-deep chains are rejected before any
// pipeline state is allocated or published.
fn graphicsPipelinePNext(raw: ?*const anyopaque, legacy: u32) ?GraphicsPipelinePNextState {
    if (raw == null) {
        if (legacy != 0) return null;
        return .{ .flags = 0 };
    }
    var next = raw;
    var depth: usize = 0;
    var seen_flags2 = false;
    var seen_rendering = false;
    var seen_robustness = false;
    var effective_flags = legacy;
    var rendering: ?PipelineRenderingState = null;
    while (next) |item| {
        if (depth == 16) return null;
        const header: *const ChainHeader = @ptrCast(@alignCast(item));
        switch (header.s_type) {
            pipeline_create_flags2_stype => {
                if (seen_flags2) return null;
                const flags2: *const PipelineCreateFlags2CreateInfo = @ptrCast(@alignCast(item));
                if (flags2.flags & ~@as(u64, pipeline_create_dispatch_base_bit) != 0) return null;
                // Graphics pipelines do not support dispatch-base; a promoted
                // zero node still overrides the legacy field as required.
                effective_flags = @truncate(flags2.flags);
                if (effective_flags != 0) return null;
                seen_flags2 = true;
            },
            pipeline_rendering_create_info_stype => {
                if (seen_rendering) return null;
                const info: *const PipelineRenderingCreateInfo = @ptrCast(@alignCast(item));
                if (info.view_mask != 0 or info.color_attachment_count > 1 or (info.color_attachment_count != 0 and (info.color_attachment_formats == null or info.color_attachment_formats.?[0] != 44)) or (info.depth_attachment_format != 0 and info.depth_attachment_format != 126) or info.stencil_attachment_format != 0) return null;
                const color_format = if (info.color_attachment_count == 0) 0 else info.color_attachment_formats.?[0];
                // ZPU's dynamic-rendering attachment path is deliberately
                // bounded to the same formats accepted by vkCmdBeginRendering.
                if (color_format != 0 and color_format != 44) return null;
                rendering = .{ .view_mask = info.view_mask, .color_format = color_format, .depth_format = info.depth_attachment_format, .stencil_format = info.stencil_attachment_format };
                seen_rendering = true;
            },
            pipeline_robustness_create_info_stype => {
                if (seen_robustness or !pipelineRobustnessNodeValid(item)) return null;
                seen_robustness = true;
            },
            else => return null,
        }
        next = header.p_next;
        depth += 1;
    }
    if (effective_flags != 0) return null;
    return .{ .flags = effective_flags, .rendering = rendering };
}

fn pipelineRenderingCompatibility(state: PipelineRenderingState) CanonicalError!Canonical {
    var w: CanonicalWriter = .{};
    defer w.deinit();
    try w.header(6);
    try w.u32le(1); // dynamic_rendering_v1
    try w.u32le(state.view_mask);
    try w.i32le(state.color_format);
    try w.i32le(state.depth_format);
    try w.i32le(state.stencil_format);
    return w.done();
}

const SemaphoreCreatePNextState = struct { timeline: bool = false, initial_value: u64 = 0 };

// External handle export is intentionally a no-op in ZPU's process-local
// profile. A zero handle-type mask is accepted as a well-formed ABI node,
// while requests for an actual OS handle remain rejected.
fn fenceCreatePNextValid(raw: ?*const anyopaque) bool {
    var next = raw;
    var depth: usize = 0;
    var saw_export = false;
    while (next) |item| {
        if (depth == 16) return false;
        const header: *const ChainHeader = @ptrCast(@alignCast(item));
        if (header.s_type != 1000113000 or saw_export) return false;
        const export_info: *const ExportFenceCreateInfo = @ptrCast(@alignCast(item));
        if (export_info.handle_types != 0) return false;
        saw_export = true;
        next = header.p_next;
        depth += 1;
    }
    return true;
}

fn semaphoreCreatePNextState(raw: ?*const anyopaque) ?SemaphoreCreatePNextState {
    var next = raw;
    var depth: usize = 0;
    var state = SemaphoreCreatePNextState{};
    var saw_timeline = false;
    var saw_export = false;
    while (next) |item| {
        if (depth == 16) return null;
        const header: *const ChainHeader = @ptrCast(@alignCast(item));
        switch (header.s_type) {
            1000207002 => {
                if (saw_timeline) return null;
                const type_info: *const SemaphoreTypeCreateInfo = @ptrCast(@alignCast(item));
                if (type_info.semaphore_type != 1) return null;
                state.timeline = true;
                state.initial_value = type_info.initial_value;
                saw_timeline = true;
            },
            1000077000 => {
                if (saw_export) return null;
                const export_info: *const ExportSemaphoreCreateInfo = @ptrCast(@alignCast(item));
                if (export_info.handle_types != 0) return null;
                saw_export = true;
            },
            else => return null,
        }
        next = header.p_next;
        depth += 1;
    }
    return state;
}

