fn coreFeaturePayloadWords(s_type: i32) ?usize {
    return switch (s_type) {
        1000145001, 1000156004, 1000063000, 1000261000, 1000207000, 1000221000, 1000253000, 1000175000, 1000108000, 1000241000, 1000295000, 1000314007, 1000066000, 1000413000, 1000215000, 1000276000, 1000297000, 1000325000, 1000335000, 1000280000, 1000044003, 1000388000, 1000265000, 1000470000, 1000545000, 1000270000, 1000528000, 1000544000, 1000466000, 1000068001, 1000232000 => 1,
        1000120000, 1000180000, 1000082000, 1000225002, 1000138000, 1000416000, 1000190002 => 2,
        1000053001, 1000211000, 1000257000, 1000177000 => 3,
        1000083000 => 4,
        1000259000 => 6,
        49 => 12,
        53 => 15,
        1000161001 => 20,
        55 => 21,
        51 => 47,
        else => null,
    };
}

fn coreFeatureChainValid(raw: ?*anyopaque) bool {
    var next = raw;
    var depth: usize = 0;
    var seen: [16]i32 = undefined;
    var seen_count: usize = 0;
    while (next) |item| {
        const header: *const ChainHeader = @ptrCast(@alignCast(item));
        if (depth == 16 or coreFeaturePayloadWords(header.s_type) == null) return false;
        for (seen[0..seen_count]) |prior| if (prior == header.s_type) return false;
        seen[seen_count] = header.s_type;
        seen_count += 1;
        next = if (header.p_next) |p| @ptrCast(@constCast(p)) else null;
        depth += 1;
    }
    return true;
}

fn populateCoreFeatureChain(raw: ?*anyopaque) bool {
    if (!coreFeatureChainValid(raw)) return false;
    var next = raw;
    while (next) |item| {
        const header: *const ChainHeader = @ptrCast(@alignCast(item));
        const words = coreFeaturePayloadWords(header.s_type) orelse return false;
        const bytes: [*]u8 = @ptrCast(item);
        @memset(bytes[16 .. 16 + words * @sizeOf(u32)], 0);
        next = if (header.p_next) |p| @ptrCast(@constCast(p)) else null;
    }
    return true;
}

fn coreFeatureChainHasEnabledValue(raw: ?*const anyopaque) bool {
    var next = raw;
    while (next) |item| {
        const header: *const ChainHeader = @ptrCast(@alignCast(item));
        const words = coreFeaturePayloadWords(header.s_type) orelse return true;
        const bytes: [*]const u8 = @ptrCast(item);
        for (bytes[16 .. 16 + words * @sizeOf(u32)]) |value| if (value != 0) return true;
        next = header.p_next;
    }
    return false;
}

// VkDeviceCreateInfo may carry the loader's VkLayerDeviceCreateInfo chain
// followed by either VkPhysicalDeviceFeatures2 or individual core-promoted
// feature structs.  Keep loader callback discovery independent, but validate
// and inspect the application feature tail instead of silently ignoring it.
fn deviceCreatePNextValid(raw: ?*const anyopaque) bool {
    var next = raw;
    var depth: usize = 0;
    var saw_loader = false;
    var saw_group = false;
    while (next) |item| {
        if (depth == 48) return false;
        const header: *const ChainHeader = @ptrCast(@alignCast(item));
        if (header.s_type == 48) {
            saw_loader = true;
            next = header.p_next;
            depth += 1;
            continue;
        }
        if (header.s_type == 1000070001) {
            if (saw_group) return false;
            const group: *const DeviceGroupDeviceCreateInfo = @ptrCast(@alignCast(item));
            // ZPU exposes one physical device.  A device-group chain is still
            // accepted for ABI compatibility, but only the single-member
            // form can be represented by this implementation.
            if (group.physical_device_count > 1 or (group.physical_device_count != 0 and group.physical_devices == null)) return false;
            saw_group = true;
            next = header.p_next;
            depth += 1;
            continue;
        }
        if (header.s_type == 1000059000) {
            const feature2: *const PhysicalDeviceFeatures2 = @ptrCast(@alignCast(item));
            return coreFeatureChainValid(feature2.p_next);
        }
        if (saw_loader and coreFeaturePayloadWords(header.s_type) == null) return true;
        return coreFeatureChainValid(@ptrCast(@constCast(item)));
    }
    return true;
}

fn deviceCreatePNextHasEnabledFeature(raw: ?*const anyopaque) bool {
    var next = raw;
    var saw_loader = false;
    while (next) |item| {
        const header: *const ChainHeader = @ptrCast(@alignCast(item));
        if (header.s_type == 48) {
            saw_loader = true;
            next = header.p_next;
            continue;
        }
        if (header.s_type == 1000070001) {
            next = header.p_next;
            continue;
        }
        if (header.s_type == 1000059000) {
            const feature2: *const PhysicalDeviceFeatures2 = @ptrCast(@alignCast(item));
            for (feature2.features.values) |value| if (value != 0) return true;
            return coreFeatureChainHasEnabledValue(feature2.p_next);
        }
        if (saw_loader and coreFeaturePayloadWords(header.s_type) == null) return false;
        return coreFeatureChainHasEnabledValue(@ptrCast(@constCast(item)));
    }
    return false;
}

fn deviceGroupPhysicalsValidLocked(p: Physical, raw: ?*const anyopaque) bool {
    var next = raw;
    var depth: usize = 0;
    while (next) |item| {
        if (depth == 48) return false;
        const header: *const ChainHeader = @ptrCast(@alignCast(item));
        if (header.s_type == 1000070001) {
            const group: *const DeviceGroupDeviceCreateInfo = @ptrCast(@alignCast(item));
            if (group.physical_device_count > 1) return false;
            if (group.physical_device_count == 1) {
                const devices = group.physical_devices orelse return false;
                if (devices[0] != p) return false;
            }
        }
        next = header.p_next;
        depth += 1;
    }
    return true;
}

fn deviceQueuePNextValid(raw: ?*const anyopaque) bool {
    var next = raw;
    var depth: usize = 0;
    var saw_priority = false;
    while (next) |item| {
        const header: *const ChainHeader = @ptrCast(@alignCast(item));
        if (depth == 16 or header.s_type != 1000174000 or saw_priority) return false;
        const priority: *const DeviceQueueGlobalPriorityCreateInfo = @ptrCast(@alignCast(item));
        // The single ZPU queue is exposed at the ordinary medium priority.
        if (priority.global_priority != 256) return false;
        saw_priority = true;
        next = header.p_next;
        depth += 1;
    }
    return true;
}

fn corePropertyPayloadBytes(s_type: i32) ?usize {
    return switch (s_type) {
        1000145002 => 8,
        1000071004 => 48,
        1000094000, 1000168000, 1000199000, 1000225000, 1000068002 => 16,
        1000117000, 1000053002, 1000413001, 1000130000, 1000259002, 1000525000 => 8,
        1000196000 => 520,
        50 => 96,
        52 => 720,
        1000207001 => 8,
        1000197000 => 72,
        1000161002 => 96,
        54 => 200,
        1000138001 => 24,
        1000280001 => 120,
        1000281001 => 32,
        56 => 128,
        1000470001 => 24,
        1000545001 => 12,
        1000270001 => 56,
        1000080000 => 8,
        else => null,
    };
}

fn propertyWriteU32(bytes: []u8, offset: usize, value: u32) void {
    std.mem.writeInt(u32, @ptrCast(bytes[offset..].ptr), value, .little);
}

fn propertyWriteU64(bytes: []u8, offset: usize, value: u64) void {
    std.mem.writeInt(u64, @ptrCast(bytes[offset..].ptr), value, .little);
}

fn populatePromotedPropertyPayload(s_type: i32, bytes: []u8) void {
    // The payload starts immediately after VkStructureType and pNext.  Keep
    // this offset table in terms of the public Vulkan structs' fields so that
    // the opaque storage remains an exact LP64 ABI while returning useful,
    // truthful values for callers that use the aggregate promoted nodes.
    switch (s_type) {
        1000145002 => { // VkPhysicalDeviceProtectedMemoryProperties
            // Protected submissions are not exposed by this CPU profile.
            propertyWriteU32(bytes, 0, 0);
        },
        1000094000 => { // VkPhysicalDeviceSubgroupProperties
            // Subgroup execution is not part of the straight-line profile.
            propertyWriteU32(bytes, 0, 0);
            propertyWriteU32(bytes, 4, 0);
            propertyWriteU32(bytes, 8, 0);
            propertyWriteU32(bytes, 12, 0);
        },
        1000168000 => { // VkPhysicalDeviceMaintenance3Properties
            propertyWriteU32(bytes, 0, 1024);
            propertyWriteU64(bytes, 8, heap_size);
        },
        1000117000 => { // VkPhysicalDevicePointClippingProperties
            propertyWriteU32(bytes, 0, 0); // VK_POINT_CLIPPING_BEHAVIOR_ALL_CLIP_PLANES
        },
        1000053002 => { // VkPhysicalDeviceMultiviewProperties
            propertyWriteU32(bytes, 0, max_image_array_layers);
            propertyWriteU32(bytes, 4, 0xffff_ffff);
        },
        1000207001 => { // VkPhysicalDeviceTimelineSemaphoreProperties
            propertyWriteU64(bytes, 0, 0);
        },
        1000197000 => { // VkPhysicalDeviceFloatControlsProperties
            // All float-control independence/preservation capabilities are
            // unadvertised and therefore remain zero.
        },
        1000161002 => { // VkPhysicalDeviceDescriptorIndexingProperties
            // Descriptor indexing update-after-bind is not advertised.
        },
        1000130000 => { // VkPhysicalDeviceSamplerFilterMinmaxProperties
            // Filter min/max is not advertised.
        },
        1000199000 => { // VkPhysicalDeviceDepthStencilResolveProperties
            // The CPU raster path is single-sample and has no resolve modes.
        },
        1000413001 => { // VkPhysicalDeviceMaintenance4Properties
            propertyWriteU64(bytes, 0, heap_size);
        },
        1000225000 => { // VkPhysicalDeviceSubgroupSizeControlProperties
            // No subgroup-size controls are exposed.
        },
        1000138001 => { // VkPhysicalDeviceInlineUniformBlockProperties
            // Inline uniform blocks are not advertised.
        },
        1000280001 => { // VkPhysicalDeviceShaderIntegerDotProductProperties
            // Integer dot-product acceleration is not advertised.
        },
        1000281001 => { // VkPhysicalDeviceTexelBufferAlignmentProperties
            propertyWriteU64(bytes, 0, 256);
            propertyWriteU32(bytes, 8, 0);
            propertyWriteU64(bytes, 16, 256);
            propertyWriteU32(bytes, 24, 0);
        },
        1000470001 => { // VkPhysicalDeviceMaintenance5Properties
            // Maintenance-5 optional line/sample behaviors are unadvertised.
        },
        1000545001 => { // VkPhysicalDeviceMaintenance6Properties
            // Maintenance-6 optional attachment behaviors are unadvertised.
        },
        1000270001 => { // VkPhysicalDeviceHostImageCopyProperties
            // ZPU's host copies use one stable optimal-tile layout and the
            // same memory requirements for host/device access.
            @memcpy(bytes[32..48], &pipeline_cache_uuid);
            propertyWriteU32(bytes, 48, 1);
        },
        1000080000 => { // VkPhysicalDevicePushDescriptorProperties
            // Push descriptors are not advertised by the feature profile.
        },
        1000068002 => { // VkPhysicalDevicePipelineRobustnessProperties
            // Robustness controls are not advertised.
        },
        1000259002 => { // VkPhysicalDeviceLineRasterizationProperties
            propertyWriteU32(bytes, 0, 4);
        },
        1000525000 => { // VkPhysicalDeviceVertexAttributeDivisorProperties
            propertyWriteU32(bytes, 0, 1);
            propertyWriteU32(bytes, 4, 1);
        },
        50 => { // VkPhysicalDeviceVulkan11Properties
            @memcpy(bytes[0..16], &device_uuid);
            @memcpy(bytes[16..32], &driver_uuid);
            // A userspace CPU ICD has no PCI LUID; the UUID and one-device
            // node mask are still stable and meaningful.
            propertyWriteU32(bytes, 40, 1); // deviceNodeMask
            propertyWriteU32(bytes, 44, 0); // deviceLUIDValid
            // Optional subgroup/multiview/protected capabilities remain zero
            // because the corresponding features are deliberately false.
            propertyWriteU32(bytes, 68, 256); // maxMultiviewViewCount
            propertyWriteU32(bytes, 72, 0xffff_ffff); // maxMultiviewInstanceIndex
            propertyWriteU32(bytes, 76, 0); // protectedNoFault
            propertyWriteU32(bytes, 80, 1024); // maxPerSetDescriptors
            propertyWriteU64(bytes, 88, heap_size); // maxMemoryAllocationSize
        },
        52 => { // VkPhysicalDeviceVulkan12Properties
            propertyWriteU32(bytes, 0, 13); // VK_DRIVER_ID_MESA_LLVMPIPE
            @memcpy(bytes[4 .. 4 + driver_name.len], driver_name);
            @memcpy(bytes[260 .. 260 + driver_info.len], driver_info);
            // Conformance and optional shader/descriptor properties stay
            // zero: this profile does not advertise Vulkan 1.2 features.
            propertyWriteU64(bytes, 704, 0); // maxTimelineSemaphoreValueDifference
            propertyWriteU32(bytes, 712, 0); // framebufferIntegerColorSampleCounts
        },
        54 => { // VkPhysicalDeviceVulkan13Properties
            // No subgroup or inline-uniform feature is exposed.  The one
            // useful promoted limit is the bounded buffer size enforced by
            // createBuffer and the device heap.
            propertyWriteU64(bytes, 192, heap_size); // maxBufferSize
        },
        56 => { // VkPhysicalDeviceVulkan14Properties
            propertyWriteU32(bytes, 0, 4); // lineSubPixelPrecisionBits
            propertyWriteU32(bytes, 4, 1); // maxVertexAttribDivisor
            propertyWriteU32(bytes, 8, 1); // supportsNonZeroFirstInstance
            // Push descriptors, local-read, robustness, and host-copy layout
            // arrays remain zero because their features are unadvertised.
            @memcpy(bytes[104..120], &pipeline_cache_uuid);
            propertyWriteU32(bytes, 120, 1); // identicalMemoryTypeRequirements
        },
        else => {},
    }
}

fn corePropertyChainValid(raw: ?*anyopaque) bool {
    var next = raw;
    var depth: usize = 0;
    var seen: [16]i32 = undefined;
    var seen_count: usize = 0;
    while (next) |item| {
        const header: *const ChainHeader = @ptrCast(@alignCast(item));
        if (depth == 16 or corePropertyPayloadBytes(header.s_type) == null) return false;
        for (seen[0..seen_count]) |prior| if (prior == header.s_type) return false;
        seen[seen_count] = header.s_type;
        seen_count += 1;
        next = if (header.p_next) |p| @ptrCast(@constCast(p)) else null;
        depth += 1;
    }
    return true;
}

fn populateCorePropertyChain(raw: ?*anyopaque) bool {
    if (!corePropertyChainValid(raw)) return false;
    var next = raw;
    while (next) |item| {
        const header: *const ChainHeader = @ptrCast(@alignCast(item));
        const bytes_len = corePropertyPayloadBytes(header.s_type) orelse return false;
        const bytes: [*]u8 = @ptrCast(item);
        @memset(bytes[16 .. 16 + bytes_len], 0);
        populatePromotedPropertyPayload(header.s_type, bytes[16 .. 16 + bytes_len]);
        switch (header.s_type) {
            1000071004 => {
                const out: *PhysicalDeviceIDProperties = @ptrCast(@alignCast(item));
                out.device_uuid = device_uuid;
                out.driver_uuid = driver_uuid;
                // CPU processes do not expose a PCI-style LUID.  The node
                // mask still identifies the one logical device.
                out.device_node_mask = 1;
                out.device_luid_valid = 0;
            },
            1000196000 => {
                const out: *PhysicalDeviceDriverProperties = @ptrCast(@alignCast(item));
                // VK_DRIVER_ID_MESA_LLVMPIPE is the registered software-CPU
                // driver class closest to this experimental ICD.  The name
                // and info strings remain the authoritative ZPU identity.
                out.driver_id = 13;
                @memcpy(out.driver_name[0..driver_name.len], driver_name);
                @memcpy(out.driver_info[0..driver_info.len], driver_info);
                out.conformance_version = .{ .major = 0, .minor = 0, .subminor = 0, .patch = 0 };
            },
            else => {},
        }
        next = if (header.p_next) |p| @ptrCast(@constCast(p)) else null;
    }
    return true;
}

fn physicalDeviceImageFormatInfo2ChainValid(raw: ?*const anyopaque, format: i32) bool {
    var next = raw;
    var depth: usize = 0;
    var seen_external = false;
    var seen_format_list = false;
    var seen_stencil = false;
    while (next) |item| {
        const header: *const ChainHeader = @ptrCast(@alignCast(item));
        switch (header.s_type) {
            1000071000 => {
                if (seen_external) return false;
                seen_external = true;
            },
            1000147000 => {
                if (seen_format_list) return false;
                seen_format_list = true;
                const formats: *const ImageFormatListCreateInfo = @ptrCast(@alignCast(item));
                if (formats.view_format_count > max_api_items or (formats.view_format_count != 0 and formats.view_formats == null)) return false;
                if (formats.view_formats) |items| for (items[0..formats.view_format_count]) |view_format| if (view_format != format) return false;
            },
            1000246000 => {
                if (seen_stencil) return false;
                seen_stencil = true;
                const stencil: *const ImageStencilUsageCreateInfo = @ptrCast(@alignCast(item));
                if (stencil.stencil_usage != 0) return false;
            },
            else => return false,
        }
        if (depth == 16) return false;
        next = header.p_next;
        depth += 1;
    }
    return true;
}

const BufferCreatePNextState = struct { valid: bool = true, has_usage: bool = false, usage: u64 = 0 };

fn bufferCreatePNextState(raw: ?*const anyopaque) BufferCreatePNextState {
    var next = raw;
    var depth: usize = 0;
    var state = BufferCreatePNextState{};
    var saw_external = false;
    var saw_capture = false;
    while (next) |item| {
        if (depth == 16) {
            state.valid = false;
            return state;
        }
        const header: *const ChainHeader = @ptrCast(@alignCast(item));
        switch (header.s_type) {
            1000072000 => {
                if (saw_external) {
                    state.valid = false;
                    return state;
                }
                const external: *const ExternalMemoryBufferCreateInfo = @ptrCast(@alignCast(item));
                if (external.handle_types != 0) {
                    state.valid = false;
                    return state;
                }
                saw_external = true;
            },
            1000257000 => {
                if (saw_capture) {
                    state.valid = false;
                    return state;
                }
                const capture: *const BufferOpaqueCaptureAddressCreateInfo = @ptrCast(@alignCast(item));
                if (capture.opaque_capture_address != 0) {
                    state.valid = false;
                    return state;
                }
                saw_capture = true;
            },
            1000470006 => {
                if (state.has_usage) {
                    state.valid = false;
                    return state;
                }
                const usage: *const BufferUsageFlags2CreateInfo = @ptrCast(@alignCast(item));
                if (usage.usage > std.math.maxInt(u32)) {
                    state.valid = false;
                    return state;
                }
                state.has_usage = true;
                state.usage = usage.usage;
            },
            else => {
                state.valid = false;
                return state;
            },
        }
        next = header.p_next;
        depth += 1;
    }
    return state;
}

fn bufferCreatePNextValid(raw: ?*const anyopaque) bool {
    return bufferCreatePNextState(raw).valid;
}

const ImageViewCreatePNextState = struct { valid: bool = true, has_usage: bool = false, usage: u32 = 0 };

fn imageViewCreatePNextState(raw: ?*const anyopaque) ImageViewCreatePNextState {
    var next = raw;
    var depth: usize = 0;
    var state = ImageViewCreatePNextState{};
    while (next) |item| {
        if (depth == 16) {
            state.valid = false;
            return state;
        }
        const header: *const ChainHeader = @ptrCast(@alignCast(item));
        if (header.s_type != 1000117002 or state.has_usage) {
            state.valid = false;
            return state;
        }
        const usage = @as(*const ImageViewUsageCreateInfo, @ptrCast(@alignCast(item)));
        state.has_usage = true;
        state.usage = usage.usage;
        next = header.p_next;
        depth += 1;
    }
    return state;
}

fn imageCreatePNextValid(raw: ?*const anyopaque, format: i32) bool {
    var next = raw;
    var depth: usize = 0;
    var saw_format_list = false;
    var saw_stencil = false;
    var saw_external = false;
    while (next) |item| {
        const header: *const ChainHeader = @ptrCast(@alignCast(item));
        switch (header.s_type) {
            1000147000 => {
                if (saw_format_list) return false;
                saw_format_list = true;
                const formats: *const ImageFormatListCreateInfo = @ptrCast(@alignCast(item));
                if (formats.view_format_count > max_api_items or (formats.view_format_count != 0 and formats.view_formats == null)) return false;
                if (formats.view_formats) |items| for (items[0..formats.view_format_count]) |view_format| if (view_format != format) return false;
            },
            1000246000 => {
                if (saw_stencil) return false;
                saw_stencil = true;
                const stencil: *const ImageStencilUsageCreateInfo = @ptrCast(@alignCast(item));
                if (stencil.stencil_usage != 0) return false;
            },
            1000072001 => {
                if (saw_external) return false;
                saw_external = true;
                const external: *const ExternalMemoryImageCreateInfo = @ptrCast(@alignCast(item));
                if (external.handle_types != 0) return false;
            },
            else => return false,
        }
        if (depth == 16) return false;
        next = header.p_next;
        depth += 1;
    }
    return true;
}

fn physicalDeviceImageFormatInfo2ExternalHandleType(raw: ?*const anyopaque) u32 {
    var next = raw;
    while (next) |item| {
        const header: *const ChainHeader = @ptrCast(@alignCast(item));
        if (header.s_type == 1000071000) return @as(*const PhysicalDeviceExternalImageFormatInfo, @ptrCast(@alignCast(item))).handle_type;
        next = header.p_next;
    }
    return 0;
}

fn imageFormatProperties2ChainValid(raw: ?*anyopaque) bool {
    var next = raw;
    var depth: usize = 0;
    var seen_external = false;
    var seen_ycbcr = false;
    var seen_host_copy = false;
    while (next) |item| {
        const header: *const ChainHeader = @ptrCast(@alignCast(item));
        if (depth == 16) return false;
        switch (header.s_type) {
            1000071001 => {
                if (seen_external) return false;
                seen_external = true;
            },
            1000156005 => {
                if (seen_ycbcr) return false;
                seen_ycbcr = true;
            },
            1000270009 => {
                if (seen_host_copy) return false;
                seen_host_copy = true;
            },
            else => return false,
        }
        next = if (header.p_next) |p| @ptrCast(@constCast(p)) else null;
        depth += 1;
    }
    return true;
}

fn populateImageFormatProperties2Chain(raw: ?*anyopaque) void {
    var next = raw;
    while (next) |item| {
        const header: *const ChainHeader = @ptrCast(@alignCast(item));
        switch (header.s_type) {
            1000071001 => {
                const properties: *ExternalImageFormatProperties = @ptrCast(@alignCast(item));
                properties.external_memory_properties = std.mem.zeroes(ExternalMemoryProperties);
            },
            1000156005 => {
                const properties: *SamplerYcbcrConversionImageFormatProperties = @ptrCast(@alignCast(item));
                properties.combined_image_sampler_descriptor_count = 0;
            },
            1000270009 => {
                const properties: *HostImageCopyDevicePerformanceQuery = @ptrCast(@alignCast(item));
                properties.optimal_device_access = 1;
                properties.identical_memory_layout = 1;
            },
            else => unreachable,
        }
        next = if (header.p_next) |p| @ptrCast(@constCast(p)) else null;
    }
}

fn formatProperties3ChainValid(raw: ?*anyopaque) bool {
    var next = raw;
