    if (!deviceQueuePNextValid(qi.p_next)) {
        hit(.queue_pnext);
        return .error_initialization_failed;
    }
    if (qi.flags != 0) {
        hit(.queue_flags);
        return .error_initialization_failed;
    }
    if (qi.family != 0) {
        hit(.queue_family);
        return .error_initialization_failed;
    }
    if (qi.count != 1) {
        hit(.queue_count);
        return .error_initialization_failed;
