        hit(.queue_priorities_null);
        return .error_initialization_failed;
    }
    const priority = qi.priorities.?[0];
    if (!std.math.isFinite(priority)) {
        hit(.priority_nonfinite);
        return .error_initialization_failed;
    }
    if (priority < 0) {
        hit(.priority_below_zero);
        return .error_initialization_failed;
