fn record(cb: CommandBuffer, command: Command) void {
    if (cb.impl.state != 1 or cb.impl.count == cb.impl.commands.len) {
        cb.impl.invalid = true;
        return;
    }
    var owned = command;
    if (cb.impl.dynamic_rendering) {
        switch (owned) {
            .render_clear => |*clear| {
                clear.color_base_layer = cb.impl.dynamic_color_base_layer;
                clear.depth_base_layer = cb.impl.dynamic_depth_base_layer;
                clear.layer_count = cb.impl.dynamic_layer_count;
            },
            .cube_draw => |*draw| {
                draw.color_base_layer = cb.impl.dynamic_color_base_layer;
                draw.depth_base_layer = cb.impl.dynamic_depth_base_layer;
                draw.layer_count = cb.impl.dynamic_layer_count;
            },
            .indirect_draw => |*draw| {
                draw.color_base_layer = cb.impl.dynamic_color_base_layer;
                draw.depth_base_layer = cb.impl.dynamic_depth_base_layer;
                draw.layer_count = cb.impl.dynamic_layer_count;
            },
            else => {},
        }
    } else if (cb.impl.active_framebuffer) |framebuffer| {
        switch (owned) {
            .render_clear => |*clear| clear.layer_count = framebuffer.layers,
            .clear_depth => |*clear| clear.layer_count = framebuffer.layers,
            .cube_draw => |*draw| draw.layer_count = framebuffer.layers,
            .indirect_draw => |*draw| draw.layer_count = framebuffer.layers,
            else => {},
        }
    }
    cb.impl.commands[cb.impl.count] = owned;
    cb.impl.count += 1;
}
fn commandForSecondaryExecution(command: Command, framebuffer: ?*FramebufferObj, dynamic_color: ?*ImageObj, dynamic_depth: ?*ImageObj, color_layout: i32, depth_layout: i32, dynamic_color_base_layer: u32, dynamic_depth_base_layer: u32, dynamic_layer_count: u32) Command {
    var result = command;
    switch (result) {
        .cube_draw => |*draw| if (draw.framebuffer == null) {
            if (dynamic_color != null or dynamic_depth != null) {
                draw.color_image = dynamic_color;
                draw.depth_image = dynamic_depth;
                draw.color_base_layer = dynamic_color_base_layer;
                draw.depth_base_layer = dynamic_depth_base_layer;
                draw.layer_count = dynamic_layer_count;
                draw.expected_color_layout = color_layout;
                draw.expected_depth_layout = depth_layout;
            } else {
                draw.framebuffer = framebuffer;
                draw.expected_color_layout = color_layout;
                draw.expected_depth_layout = depth_layout;
            }
        },
        .indirect_draw => |*draw| if (draw.framebuffer == null) {
            if (dynamic_color != null or dynamic_depth != null) {
                draw.color_image = dynamic_color;
                draw.depth_image = dynamic_depth;
                draw.color_base_layer = dynamic_color_base_layer;
                draw.depth_base_layer = dynamic_depth_base_layer;
                draw.layer_count = dynamic_layer_count;
                draw.expected_color_layout = color_layout;
                draw.expected_depth_layout = depth_layout;
            } else {
                draw.framebuffer = framebuffer;
                draw.expected_color_layout = color_layout;
                draw.expected_depth_layout = depth_layout;
            }
        },
        else => {},
    }
    return result;
}
fn cmdExecuteCommands(cb: ?CommandBuffer, count: u32, buffers: ?[*]const CommandBuffer) callconv(.c) void {
