fn supportedLayout(layout: i32) bool {
    return layout == 0 or layout == 8 or layout == 1 or layout == 2 or layout == 3 or layout == 5 or layout == 6 or layout == 7 or layout == 1_000_001_002;
}
fn renderingAttachmentLayoutValid(layout: i32, aspect_mask: u32) bool {
    // The narrow CPU render path supports GENERAL plus the matching legacy
    // color/depth attachment layouts.  Undefined, transfer, shader, present,
    // preinitialized, and cross-aspect layouts are never valid while an
    // attachment is accessed by dynamic rendering.
    return layout == 1 or (aspect_mask == 1 and layout == 2) or (aspect_mask == 2 and layout == 3);
}
fn dependencyInfoShapeValid(info: ?*const DependencyInfo) bool {
    const ci = info orelse return false;
    if (ci.s_type != 1000314003 or ci.p_next != null or ci.dependency_flags & ~@as(u32, 1) != 0 or ci.memory_barrier_count > max_api_items or ci.buffer_memory_barrier_count > max_api_items or ci.image_memory_barrier_count > max_api_items) return false;
    if ((ci.memory_barrier_count != 0 and ci.memory_barriers == null) or (ci.buffer_memory_barrier_count != 0 and ci.buffer_memory_barriers == null) or (ci.image_memory_barrier_count != 0 and ci.image_memory_barriers == null)) return false;
    if (ci.memory_barriers) |items| for (items[0..ci.memory_barrier_count]) |barrier| if (barrier.s_type != 1000314000 or barrier.p_next != null) return false;
    if (ci.buffer_memory_barriers) |items| for (items[0..ci.buffer_memory_barrier_count]) |barrier| if (barrier.s_type != 1000314001 or barrier.p_next != null) return false;
    if (ci.image_memory_barriers) |items| for (items[0..ci.image_memory_barrier_count]) |barrier| if (barrier.s_type != 1000314002 or barrier.p_next != null) return false;
    return true;
}
fn eventDependencyInfoFlagsValid(info: *const DependencyInfo) bool {
    // BY_REGION is valid for pipeline barriers but explicitly forbidden for
    // event2 signal/wait dependencies.  The optional asymmetric-event bit is
    // not advertised by this device, so only the core zero form is accepted.
    return info.dependency_flags == 0;
}
fn eventSetDependencyStagesValid(info: *const DependencyInfo) bool {
    if (info.memory_barriers) |items| for (items[0..info.memory_barrier_count]) |barrier| if (barrier.src_stage_mask & 0x4000 != 0 or barrier.dst_stage_mask & 0x4000 != 0) return false;
    if (info.buffer_memory_barriers) |items| for (items[0..info.buffer_memory_barrier_count]) |barrier| if (barrier.src_stage_mask & 0x4000 != 0 or barrier.dst_stage_mask & 0x4000 != 0) return false;
    if (info.image_memory_barriers) |items| for (items[0..info.image_memory_barrier_count]) |barrier| if (barrier.src_stage_mask & 0x4000 != 0 or barrier.dst_stage_mask & 0x4000 != 0) return false;
    return true;
}

// Synchronization2 promotes several stage/access bits into the 64-bit ABI.
// ZPU's execution core intentionally retains the compact Vulkan 1.0 masks,
// so normalize only aliases whose semantics are represented exactly by that
// core.  Unknown high bits remain rejected before command-buffer mutation.
fn sync2StageMaskToLegacy(mask: u64) ?u32 {
    const high_transfer = @as(u64, 0x1000_0000_0) | @as(u64, 0x2000_0000_0) | @as(u64, 0x4000_0000_0) | @as(u64, 0x8000_0000_0);
    const high_vertex_input = @as(u64, 0x1000_0000_00) | @as(u64, 0x2000_0000_00);
    const high_vertex_shader = @as(u64, 0x4000_0000_00);
    const supported = @as(u64, 0x1_ffff) | high_transfer | high_vertex_input | high_vertex_shader;
    if (mask & ~supported != 0) return null;
    var legacy: u32 = @truncate(mask & 0x1_ffff);
    if (mask & high_transfer != 0) legacy |= 0x1000; // COPY/RESOLVE/BLIT/CLEAR -> TRANSFER
    if (mask & high_vertex_input != 0) legacy |= 0x4; // INDEX/VERTEX_ATTRIBUTE_INPUT -> VERTEX_INPUT
    if (mask & high_vertex_shader != 0) legacy |= 0x8; // PRE_RASTERIZATION_SHADERS -> VERTEX_SHADER
    if (!validPipelineStageMask(legacy)) return null;
    return legacy;
}

fn sync2BarrierStageMaskToLegacy(stage_mask: u64, access_mask: u64) ?u32 {
    // Synchronization2 permits VK_PIPELINE_STAGE_2_NONE for an empty
    // synchronization scope. The compact legacy backend has no NONE stage,
    // so use its conservative ALL_COMMANDS lowering only when the matching
    // access scope is empty. A non-empty access mask with NONE is invalid
    // because no pipeline stage can make that access visible.
    if (stage_mask == 0) return if (access_mask == 0) 0x1_0000 else null;
    return sync2StageMaskToLegacy(stage_mask);
}

fn sync2AccessMaskToLegacy(mask: u64) ?u32 {
    const high_sampled = @as(u64, 0x1_0000_0000);
    const high_storage_read = @as(u64, 0x2_0000_0000);
    const high_storage_write = @as(u64, 0x4_0000_0000);
    const supported = @as(u64, 0x1_ffff) | high_sampled | high_storage_read | high_storage_write;
    if (mask & ~supported != 0) return null;
    var legacy: u32 = @truncate(mask & 0x1_ffff);
    if (mask & (high_sampled | high_storage_read) != 0) legacy |= 0x20; // SHADER_READ
    if (mask & high_storage_write != 0) legacy |= 0x40; // SHADER_WRITE
    return legacy;
}
fn sync2TimestampStageToLegacy(stage: u64) ?u32 {
    // VkCmdWriteTimestamp2 has a single-stage domain even though the
    // synchronization2 ABI uses a 64-bit flags mask for the parameter.
    if (stage == 0 or @popCount(stage) != 1) return null;
    if (stage == 0x4000) return null;
    return sync2StageMaskToLegacy(stage);
}
fn commandBufferOutsideRenderPass(command_buffer: *const CommandBufferObj) bool {
    return command_buffer.impl.active_render_pass == null and !command_buffer.impl.dynamic_rendering;
}
fn commandBufferImageLayout(command_buffer: *const CommandBufferObj, image: *const ImageObj) i32 {
    // Layout transitions are recorded, not applied, until submission. Fold
    // the command-local history over the image's live layout so a barrier
    // followed by a render pass in one command buffer is validated in the
    // same order as queue prevalidation.
    var layout = image.layout;
    for (command_buffer.impl.commands[0..command_buffer.impl.count]) |command| {
        switch (command) {
            .transition => |transition| {
                if (transition.image == image) layout = transition.new_layout;
            },
            else => {},
        }
    }
    return layout;
}
fn dynamicAttachmentLayout(command_buffer: *const CommandBufferObj, image: ?*ImageObj) i32 {
    return if (image) |value| commandBufferImageLayout(command_buffer, value) else -1;
}
fn renderPassAttachmentLayout(command_buffer: *const CommandBufferObj, color: bool) i32 {
    return if (command_buffer.impl.active_render_pass) |render_pass| blk: {
        if (command_buffer.impl.active_subpass >= render_pass.subpass_count) break :blk -1;
        if (color) {
            if (render_pass.framebuffer_attachment_count == 0 or render_pass.framebuffer_attachments[0].role != .color) break :blk -1;
            break :blk render_pass.subpass_color_layouts[command_buffer.impl.active_subpass];
        }
        const has_depth = (render_pass.framebuffer_attachment_count == 1 and render_pass.framebuffer_attachments[0].role == .depth) or
            (render_pass.framebuffer_attachment_count == 2 and render_pass.framebuffer_attachments[1].role == .depth);
        if (!has_depth) break :blk -1;
        break :blk render_pass.subpass_depth_layouts[command_buffer.impl.active_subpass];
    } else -1;
}
fn recordedAttachmentLayout(command_buffer: *const CommandBufferObj, color: bool) i32 {
    return if (command_buffer.impl.dynamic_rendering)
        dynamicAttachmentLayout(command_buffer, if (color) command_buffer.impl.dynamic_color_image else command_buffer.impl.dynamic_depth_image)
