            .query_reset => |op| {
                if (op.pool == pool and index >= op.first and index - op.first < op.count) state = 0;
            },
            .query_begin => |op| {
                if (op.pool == pool and op.index == index) state = 1;
            },
            .query_end => |op| {
                if (op.pool == pool and op.index == index) state = 2;
            },
            .query_timestamp => |op| {
