            if (op.dst.owner != owner or op.dst.memory.?.owner != owner) return wrongSubmittingDevice();
        },
        .update_buffer => |op| {
            if (!liveBufferObject(op.dst) or op.dst.memory == null or !liveMemoryObject(op.dst.memory.?)) return deadResource();
            if (op.dst.owner != owner or op.dst.memory.?.owner != owner) return wrongSubmittingDevice();
