}

fn emptyRect() cpu_cube.Rect {
    return .{ .x = 0, .y = 0, .width = 0, .height = 0 };
}

fn unionRect(a: cpu_cube.Rect, b: cpu_cube.Rect) cpu_cube.Rect {
    if (a.width == 0 or a.height == 0) return b;
    if (b.width == 0 or b.height == 0) return a;
    const x0 = @min(a.x, b.x);
    const y0 = @min(a.y, b.y);
    const x1 = @max(a.x + @as(i32, @intCast(a.width)), b.x + @as(i32, @intCast(b.width)));
    const y1 = @max(a.y + @as(i32, @intCast(a.height)), b.y + @as(i32, @intCast(b.height)));
    return .{ .x = x0, .y = y0, .width = @intCast(x1 - x0), .height = @intCast(y1 - y0) };
}

fn fillImagePatternRect(bytes: []u8, width: u32, rect: cpu_cube.Rect, pattern: u32) void {
    if (rect.width == 0 or rect.height == 0) return;
    const aligned: []align(4) u8 = @alignCast(bytes);
    const words = std.mem.bytesAsSlice(u32, aligned);
    const x: usize = @intCast(rect.x);
    const first_y: usize = @intCast(rect.y);
    for (first_y..first_y + rect.height) |y| {
        const start = y * width + x;
        @memset(words[start..][0..rect.width], pattern);
    }
}

fn blitCoordinate(start: i32, end: i32, index: u32, destination_span: u32, source_span: u32) usize {
    const source_index = @as(u32, @intCast((@as(u64, index) * source_span) / destination_span));
    return @intCast(if (start < end) @as(u32, @intCast(start)) + source_index else @as(u32, @intCast(start)) - source_index - 1);
}

fn linearByte(a: u8, b: u8, t: f32) u8 {
    return @intFromFloat(std.math.clamp(@as(f32, @floatFromInt(a)) * (1 - t) + @as(f32, @floatFromInt(b)) * t, 0, 255));
}

fn sampleLinear(bytes: []const u8, width: u32, height: u32, x: f32, y: f32) [4]u8 {
    const clamped_x = std.math.clamp(x, 0, @as(f32, @floatFromInt(width - 1)));
    const clamped_y = std.math.clamp(y, 0, @as(f32, @floatFromInt(height - 1)));
    const x0: usize = @intFromFloat(@floor(clamped_x));
    const y0: usize = @intFromFloat(@floor(clamped_y));
    const x1 = @min(x0 + 1, width - 1);
    const y1 = @min(y0 + 1, height - 1);
    const tx = clamped_x - @as(f32, @floatFromInt(x0));
    const ty = clamped_y - @as(f32, @floatFromInt(y0));
    const a = bytes[(y0 * width + x0) * 4 ..][0..4];
    const b = bytes[(y0 * width + x1) * 4 ..][0..4];
    const c = bytes[(y1 * width + x0) * 4 ..][0..4];
    const d = bytes[(y1 * width + x1) * 4 ..][0..4];
    var result: [4]u8 = undefined;
    for (0..4) |channel| result[channel] = linearByte(linearByte(a[channel], b[channel], tx), linearByte(c[channel], d[channel], tx), ty);
    return result;
}

fn executeBlitImage(item: BlitImageCommand) void {
    const src = imageBytes(item.src);
    const dst = imageBytes(item.dst);
    const src_layer_size: usize = @intCast(imageLayerByteSize(item.src).?);
    const src_width = blitSpan(item.region.src_offsets[0].x, item.region.src_offsets[1].x, item.src.width).?;
    const src_height = blitSpan(item.region.src_offsets[0].y, item.region.src_offsets[1].y, item.src.height).?;
    const dst_width = blitSpan(item.region.dst_offsets[0].x, item.region.dst_offsets[1].x, item.dst.width).?;
    const dst_height = blitSpan(item.region.dst_offsets[0].y, item.region.dst_offsets[1].y, item.dst.height).?;
    var layer: u32 = 0;
    while (layer < item.region.src_subresource.layer_count) : (layer += 1) {
        const src_layer_offset = imageLayerOffset(item.src, item.region.src_subresource.base_array_layer + layer).?;
        const dst_layer_offset = imageLayerOffset(item.dst, item.region.dst_subresource.base_array_layer + layer).?;
        var y: u32 = 0;
        while (y < dst_height) : (y += 1) {
            const sy = blitCoordinate(item.region.src_offsets[0].y, item.region.src_offsets[1].y, y, dst_height, src_height);
            const dy = if (item.region.dst_offsets[0].y < item.region.dst_offsets[1].y) @as(usize, @intCast(item.region.dst_offsets[0].y)) + y else @as(usize, @intCast(item.region.dst_offsets[0].y)) - y - 1;
            var x: u32 = 0;
            while (x < dst_width) : (x += 1) {
                const dx = if (item.region.dst_offsets[0].x < item.region.dst_offsets[1].x) @as(usize, @intCast(item.region.dst_offsets[0].x)) + x else @as(usize, @intCast(item.region.dst_offsets[0].x)) - x - 1;
                const destination = dst_layer_offset + (dy * item.dst.width + dx) * 4;
                if (item.filter == 1) {
                    const u = (@as(f32, @floatFromInt(x)) + 0.5) / @as(f32, @floatFromInt(dst_width));
                    const t = u * @as(f32, @floatFromInt(src_width)) - 0.5;
                    const sx = if (item.region.src_offsets[0].x < item.region.src_offsets[1].x) @as(f32, @floatFromInt(item.region.src_offsets[0].x)) + t else @as(f32, @floatFromInt(item.region.src_offsets[0].x - 1)) - t;
                    const v = (@as(f32, @floatFromInt(y)) + 0.5) / @as(f32, @floatFromInt(dst_height));
                    const ty = v * @as(f32, @floatFromInt(src_height)) - 0.5;
                    const syf = if (item.region.src_offsets[0].y < item.region.src_offsets[1].y) @as(f32, @floatFromInt(item.region.src_offsets[0].y)) + ty else @as(f32, @floatFromInt(item.region.src_offsets[0].y - 1)) - ty;
                    const sample = sampleLinear(src[src_layer_offset..][0..src_layer_size], item.src.width, item.src.height, sx, syf);
                    @memcpy(dst[destination..][0..4], &sample);
                } else {
                    const sx = blitCoordinate(item.region.src_offsets[0].x, item.region.src_offsets[1].x, x, dst_width, src_width);
                    const source = src_layer_offset + (sy * item.src.width + sx) * 4;
                    std.mem.copyForwards(u8, dst[destination..][0..4], src[source..][0..4]);
                }
            }
        }
    }
    invalidateImageContents(item.dst);
}

fn executeResolveImage(item: ResolveImageCommand) void {
    const src = imageBytes(item.src);
    const dst = imageBytes(item.dst);
    var layer: u32 = 0;
    while (layer < item.region.src_subresource.layer_count) : (layer += 1) {
        const src_layer_offset = imageLayerOffset(item.src, item.region.src_subresource.base_array_layer + layer).?;
        const dst_layer_offset = imageLayerOffset(item.dst, item.region.dst_subresource.base_array_layer + layer).?;
        var y: u32 = 0;
        while (y < item.region.extent.height) : (y += 1) {
            const source = src_layer_offset + ((@as(usize, @intCast(item.region.src_offset.y)) + y) * item.src.width + @as(usize, @intCast(item.region.src_offset.x))) * 4;
            const destination = dst_layer_offset + ((@as(usize, @intCast(item.region.dst_offset.y)) + y) * item.dst.width + @as(usize, @intCast(item.region.dst_offset.x))) * 4;
            const bytes = @as(usize, item.region.extent.width) * 4;
            std.mem.copyForwards(u8, dst[destination..][0..bytes], src[source..][0..bytes]);
        }
    }
    invalidateImageContents(item.dst);
}

fn invalidateImageContents(image: *ImageObj) void {
    image.clear_pattern = null;
    image.content_bounds = .{ .x = 0, .y = 0, .width = image.width, .height = image.height };
    image.force_full_present = true;
    image.complex_3d_content = false;
    if (image.dirty_tiles) |tiles| @memset(tiles, 0);
}

fn ensureDirtyTiles(image: *ImageObj) ?[]align(64) u8 {
    if (image.dirty_tiles) |tiles| return tiles;
    const byte_count = cpu_cube.dirtyTileByteCount(image.width, image.height);
    if (byte_count == 0 or byte_count > cpu_cube.max_dirty_tile_bytes) return null;
    const tiles = allocateBytes(byte_count) catch return null;
    @memset(tiles, 0);
    image.dirty_tiles = tiles;
    return tiles;
}

const QueryExecutionContext = struct { pool: ?*QueryPoolObj = null, index: u32 = 0 };
fn computeTypeByteSize(ty: render_ir.Type) usize {
    return @as(usize, ty.columns) * ty.rows * 4;
}
fn executeComputeDispatch(op: DispatchCommand) void {
    if (op.pipeline.executor == null) return;
    const executor: *render_ir_exec.Executor = &op.pipeline.executor.?;
    var bindings: [8]render_ir_exec.Binding = undefined;
    var binding_count: usize = 0;
    var outputs: [8]render_ir_exec.Output = undefined;
    var output_count: usize = 0;
    const descriptors = op.descriptors orelse return;
    for (executor.program.interfaces, 0..) |interface, interface_index| {
        if (interface.storage == .uniform) {
            const uniform = descriptors.uniform orelse return;
            if (interface.binding != 0 or interface.descriptor_set != 0 or descriptors.uniform_offset > uniform.size or descriptors.uniform_range == 0 or descriptors.uniform_range > uniform.size - descriptors.uniform_offset or binding_count == bindings.len) return;
            const uniform_bytes = bufferBytes(uniform)[@intCast(descriptors.uniform_offset)..][0..@intCast(descriptors.uniform_range)];
            const required = computeTypeByteSize(interface.ty);
            if (required == 0 or required > uniform_bytes.len) return;
            bindings[binding_count] = .{ .interface = @intCast(interface_index), .bytes = uniform_bytes };
            binding_count += 1;
        } else if (interface.storage == .output) {
            const storage = descriptors.storage orelse return;
            if (interface.binding != descriptors.storage_binding or interface.descriptor_set != 0 or output_count == outputs.len or descriptors.storage_offset > storage.size or descriptors.storage_range == 0 or descriptors.storage_range > storage.size - descriptors.storage_offset) return;
            const storage_bytes = bufferBytes(storage)[@intCast(descriptors.storage_offset)..][0..@intCast(descriptors.storage_range)];
            const required = computeTypeByteSize(interface.ty);
            if (required == 0 or required > storage_bytes.len) return;
            if (binding_count == bindings.len) return;
            // StorageBuffer interfaces are read/write. Expose the same
            // descriptor range to the executor as an input binding and an
            // output target so static OpLoad/OpAccessChain reads observe the
            // current contents while writes remain transactional.
            bindings[binding_count] = .{ .interface = @intCast(interface_index), .bytes = storage_bytes };
            binding_count += 1;
            outputs[output_count] = .{ .interface = @intCast(interface_index), .bytes = storage_bytes };
            output_count += 1;
        }
    }
    var invocations = std.math.mul(u64, op.groups[0], op.groups[1]) catch return;
    invocations = std.math.mul(u64, invocations, op.groups[2]) catch return;
    if (invocations == 0 or invocations > 1_048_576) return;
    var invocation: u64 = 0;
    while (invocation < invocations) : (invocation += 1) {
        executor.execute(bindings[0..binding_count], outputs[0..output_count]) catch return;
    }
}
const ProfileScreenVertex = struct { x: f32, y: f32, z: f32, w: f32 };

fn profileEdge(ax: f32, ay: f32, bx: f32, by: f32, px: f32, py: f32) f32 {
    return (px - ax) * (by - ay) - (py - ay) * (bx - ax);
}

fn profileReadClip(bytes: []const u8) ?[4]f32 {
    if (bytes.len < 16) return null;
    var result: [4]f32 = undefined;
    for (&result, 0..) |*value, index| {
        value.* = @bitCast(std.mem.readInt(u32, bytes[index * 4 ..][0..4], .little));
        if (!std.math.isFinite(value.*)) return null;
    }
    return result;
}

fn profileWriteColor(bytes: []u8, fragment_bool: bool, output: []const u8) ?u32 {
    if (fragment_bool) {
        if (output.len < 4) return null;
        const value = std.mem.readInt(u32, output[0..4], .little) != 0;
        bytes[0] = if (value) 255 else 0;
        bytes[1] = if (value) 255 else 0;
        bytes[2] = if (value) 255 else 0;
        bytes[3] = 255;
        return 1;
    }
    if (output.len < 16) return null;
    var rgba: [4]u8 = undefined;
    for (&rgba, 0..) |*value, index| {
        const component: f32 = @bitCast(std.mem.readInt(u32, output[index * 4 ..][0..4], .little));
        if (!std.math.isFinite(component)) return null;
        value.* = @intFromFloat(std.math.clamp(component, 0, 1) * 255.0);
    }
    bytes[0] = rgba[2];
    bytes[1] = rgba[1];
    bytes[2] = rgba[0];
    bytes[3] = rgba[3];
    return 1;
}

fn profileDepthCompare(op: i32, incoming: f32, stored: f32) bool {
    return switch (op) {
        0 => false,
        1 => incoming < stored,
        2 => incoming == stored,
        3 => incoming <= stored,
        4 => incoming > stored,
        5 => incoming != stored,
        6 => incoming >= stored,
        7 => true,
        else => false,
    };
}

fn profileIndexValue(indexed: IndexedDrawState, emitted: u32) ?u32 {
    const index_size: usize = if (indexed.index_type == 0) 2 else if (indexed.index_type == 1) 4 else return null;
    const at = std.math.add(usize, @intCast(indexed.offset), std.math.mul(usize, emitted, index_size) catch return null) catch return null;
    const bytes = bufferBytes(indexed.buffer);
    if (at > bytes.len or index_size > bytes.len - at) return null;
    const raw: u32 = if (index_size == 2) std.mem.readInt(u16, bytes[at..][0..2], .little) else std.mem.readInt(u32, bytes[at..][0..4], .little);
    const adjusted = @as(i64, raw) + indexed.vertex_offset;
    if (adjusted < 0 or adjusted > std.math.maxInt(u32)) return null;
    return @intCast(adjusted);
}

fn executeProfileDraw(op: anytype, query_context: *QueryExecutionContext, layer: u32) void {
    const profile = switch (op.pipeline.execution_abi) {
        .profile_v1_scalar_graphics => |*value| value,
        else => return,
    };
    const color = op.color_image orelse if (op.framebuffer) |fb| fb.color_image else null;
    const depth = op.depth_image orelse if (op.framebuffer) |fb| fb.depth_image else null;
    const target = color orelse depth orelse return;
    const color_bytes = if (color) |color_image| imageLayerBytes(color_image, op.color_base_layer + layer) else null;
    const depth_bytes = if (depth) |depth_image| imageLayerBytes(depth_image, op.depth_base_layer + layer) else null;
    if (op.vertex_count < 3 or op.vertex_count % 3 != 0 or op.vertex_count > 4096 or op.instance_count == 0) return;
    var bounds = emptyRect();
    var pixels_written: usize = 0;
    var vertex_bindings: [20]render_ir_exec.Binding = undefined;
    var vertex_binding_storage: [16][16]u8 = undefined;
    var vertex_output_bytes: [16][16]u8 = undefined;
    var vertex_outputs: [16]render_ir_exec.Output = undefined;
    for (profile.vertex_outputs[0..profile.vertex_output_count], 0..) |interface, slot| vertex_outputs[slot] = .{ .interface = interface, .bytes = &vertex_output_bytes[slot] };
    var varying_bytes: [3][8][16]u8 = undefined;
    var fragment_bindings: [12]render_ir_exec.Binding = undefined;
    var fragment_binding_storage: [8][16]u8 = undefined;
    var vertex_uniform_bindings: [4]render_ir_exec.Binding = undefined;
    var fragment_uniform_bindings: [4]render_ir_exec.Binding = undefined;
    var vertex_uniform_count: usize = 0;
    var fragment_uniform_count: usize = 0;
    var uniform_bytes: []const u8 = &.{};
    if (profile.vertex_uniform_count != 0 or profile.fragment_uniform_count != 0) {
        const uniform_buffer = op.descriptors.uniform orelse return;
        const start = op.descriptors.uniform_offset;
        const range = op.descriptors.uniform_range;
        if (start > uniform_buffer.size or range == 0 or range > uniform_buffer.size - start) return;
        uniform_bytes = bufferBytes(uniform_buffer)[@intCast(start)..][0..@intCast(range)];
        for (profile.vertex_uniforms[0..profile.vertex_uniform_count]) |uniform| {
            vertex_uniform_bindings[vertex_uniform_count] = .{ .interface = uniform.interface, .bytes = uniform_bytes };
            vertex_uniform_count += 1;
        }
        for (profile.fragment_uniforms[0..profile.fragment_uniform_count]) |uniform| {
            fragment_uniform_bindings[fragment_uniform_count] = .{ .interface = uniform.interface, .bytes = uniform_bytes };
            fragment_uniform_count += 1;
        }
    }
    var fragment_output_bytes: [16]u8 = undefined;
    var fragment_outputs = [_]render_ir_exec.Output{.{ .interface = profile.fragment_output, .bytes = &fragment_output_bytes }};
    var vertices: [3]ProfileScreenVertex = undefined;
    var triangle_start: u32 = 0;
    while (triangle_start < op.vertex_count) : (triangle_start += 3) {
        for (0..3) |corner| {
            var binding_count: usize = 0;
            for (profile.inputs[0..profile.input_count]) |input| {
                const buffer = op.vertex_bindings.buffers[input.binding] orelse return;
                const stride = if (op.pipeline.dynamic_vertex_input_binding_stride) op.vertex_bindings.strides[input.binding] else if (op.vertex_bindings.strides[input.binding] == 0) input.stride else op.vertex_bindings.strides[input.binding];
                const emitted = triangle_start + @as(u32, @intCast(corner));
                const vertex_index = if (op.indexed) |indexed| @as(u64, profileIndexValue(indexed, emitted) orelse return) else std.math.add(u64, op.base_vertex, emitted) catch return;
                const relative = std.math.add(u64, input.offset, std.math.mul(u64, vertex_index, stride) catch return) catch return;
                const start = std.math.add(u64, op.vertex_bindings.offsets[input.binding], relative) catch return;
                const source = bufferBytes(buffer);
                if (start > source.len or source.len - start < 16 or binding_count == vertex_bindings.len) return;
                @memcpy(vertex_binding_storage[binding_count][0..16], source[@intCast(start)..][0..16]);
                vertex_bindings[binding_count] = .{ .interface = input.interface, .bytes = &vertex_binding_storage[binding_count] };
                binding_count += 1;
            }
            for (vertex_uniform_bindings[0..vertex_uniform_count]) |uniform| {
                vertex_bindings[binding_count] = uniform;
                binding_count += 1;
            }
            profile.vertex.execute(vertex_bindings[0..binding_count], vertex_outputs[0..profile.vertex_output_count]) catch return;
            const clip = profileReadClip(&vertex_output_bytes[profile.vertex_position_slot]) orelse return;
            if (@abs(clip[3]) < 0.000001) return;
            const inverse_w = 1.0 / clip[3];
            const ndc_x = clip[0] * inverse_w;
            const ndc_y = clip[1] * inverse_w;
            const ndc_z = clip[2] * inverse_w;
            const x = op.viewport.x + (ndc_x * 0.5 + 0.5) * op.viewport.width;
            const y = op.viewport.y + (ndc_y * 0.5 + 0.5) * op.viewport.height;
            const z = op.viewport.min_depth + ndc_z * (op.viewport.max_depth - op.viewport.min_depth);
            if (!std.math.isFinite(x) or !std.math.isFinite(y) or !std.math.isFinite(z)) return;
            vertices[corner] = .{ .x = x, .y = y, .z = z, .w = clip[3] };
            for (profile.varyings[0..profile.varying_count], 0..) |varying, varying_index| @memcpy(varying_bytes[corner][varying_index][0..16], vertex_output_bytes[varying.vertex_slot][0..16]);
        }
        const area = profileEdge(vertices[0].x, vertices[0].y, vertices[1].x, vertices[1].y, vertices[2].x, vertices[2].y);
        if (!std.math.isFinite(area) or @abs(area) < 0.00001) continue;
        const front_facing = if (op.front_face == 0) area < 0 else area > 0;
        if ((front_facing and op.cull_mode & 1 != 0) or (!front_facing and op.cull_mode & 2 != 0)) continue;
        if (profile.varying_count == 0) {
            profile.fragment.execute(fragment_uniform_bindings[0..fragment_uniform_count], fragment_outputs[0..]) catch return;
        }
        const inverse_area = 1.0 / area;
        const min_x = @max(@as(i32, @intFromFloat(@floor(@min(vertices[0].x, @min(vertices[1].x, vertices[2].x))))), op.scissor.x, 0);
        const min_y = @max(@as(i32, @intFromFloat(@floor(@min(vertices[0].y, @min(vertices[1].y, vertices[2].y))))), op.scissor.y, 0);
        const max_x = @min(@as(i32, @intFromFloat(@ceil(@max(vertices[0].x, @max(vertices[1].x, vertices[2].x))))), op.scissor.x + @as(i32, @intCast(op.scissor.width)), @as(i32, @intCast(target.width)));
        const max_y = @min(@as(i32, @intFromFloat(@ceil(@max(vertices[0].y, @max(vertices[1].y, vertices[2].y))))), op.scissor.y + @as(i32, @intCast(op.scissor.height)), @as(i32, @intCast(target.height)));
        if (max_x <= min_x or max_y <= min_y) continue;
        for (@intCast(min_y)..@intCast(max_y)) |y| for (@intCast(min_x)..@intCast(max_x)) |x| {
            const px = @as(f32, @floatFromInt(x)) + 0.5;
            const py = @as(f32, @floatFromInt(y)) + 0.5;
            const b0 = profileEdge(vertices[1].x, vertices[1].y, vertices[2].x, vertices[2].y, px, py) * inverse_area;
            const b1 = profileEdge(vertices[2].x, vertices[2].y, vertices[0].x, vertices[0].y, px, py) * inverse_area;
            const b2 = profileEdge(vertices[0].x, vertices[0].y, vertices[1].x, vertices[1].y, px, py) * inverse_area;
            if (b0 < 0 or b1 < 0 or b2 < 0) continue;
            if (profile.varying_count != 0) {
                const q0 = b0 / vertices[0].w;
                const q1 = b1 / vertices[1].w;
                const q2 = b2 / vertices[2].w;
                const denominator = q0 + q1 + q2;
                if (!std.math.isFinite(denominator) or @abs(denominator) < 0.000001) continue;
                for (profile.varyings[0..profile.varying_count], 0..) |varying, varying_index| {
                    for (0..4) |lane| {
                        const a: f32 = @bitCast(std.mem.readInt(u32, varying_bytes[0][varying_index][lane * 4 ..][0..4], .little));
                        const b: f32 = @bitCast(std.mem.readInt(u32, varying_bytes[1][varying_index][lane * 4 ..][0..4], .little));
                        const c: f32 = @bitCast(std.mem.readInt(u32, varying_bytes[2][varying_index][lane * 4 ..][0..4], .little));
                        const value = (q0 * a + q1 * b + q2 * c) / denominator;
                        if (!std.math.isFinite(value)) return;
                        std.mem.writeInt(u32, fragment_binding_storage[varying_index][lane * 4 ..][0..4], @bitCast(value), .little);
                    }
                    fragment_bindings[varying_index] = .{ .interface = varying.fragment_interface, .bytes = &fragment_binding_storage[varying_index] };
                }
                var fragment_binding_count: usize = profile.varying_count;
                for (fragment_uniform_bindings[0..fragment_uniform_count]) |uniform| {
                    fragment_bindings[fragment_binding_count] = uniform;
                    fragment_binding_count += 1;
                }
                profile.fragment.execute(fragment_bindings[0..fragment_binding_count], fragment_outputs[0..]) catch return;
            }
            const depth_value = b0 * vertices[0].z + b1 * vertices[1].z + b2 * vertices[2].z;
            if (!std.math.isFinite(depth_value) or depth_value < 0 or depth_value > 1) continue;
            const offset = (@as(usize, @intCast(y)) * target.width + @as(usize, @intCast(x))) * 4;
            if (depth_bytes != null and op.depth_bounds_test_enable != 0 and (depth_value < op.depth_bounds[0] or depth_value > op.depth_bounds[1])) continue;
            if (depth_bytes) |depth_storage| {
                const stored_depth: f32 = @bitCast(std.mem.readInt(u32, depth_storage[offset..][0..4], .little));
                if (op.depth_test_enable != 0 and (!std.math.isFinite(stored_depth) or !profileDepthCompare(op.depth_compare_op, depth_value, stored_depth))) continue;
            }
            if (color_bytes) |color_storage| if (profileWriteColor(color_storage[offset..][0..4], profile.fragment_bool, &fragment_output_bytes) == null) return;
            if (depth_bytes) |depth_storage| if (op.depth_write_enable != 0) std.mem.writeInt(u32, depth_storage[offset..][0..4], @bitCast(depth_value), .little);
            bounds = unionRect(bounds, .{ .x = @intCast(x), .y = @intCast(y), .width = 1, .height = 1 });
            pixels_written += 1;
        };
    }
    if (query_context.pool) |query_pool| _ = query_pool.slots[query_context.index].value.fetchAdd(pixels_written, .monotonic);
    if (color) |color_image| {
        color_image.content_bounds = unionRect(color_image.content_bounds, bounds);
        color_image.complex_3d_content = true;
        color_image.force_full_present = true;
    }
    if (depth) |depth_image| depth_image.content_bounds = unionRect(depth_image.content_bounds, bounds);
}
fn executeValidatedCommand(command: Command, query_context: *QueryExecutionContext) void {
    switch (command) {
        .fill => |op| {
            const bytes = bufferBytes(op.dst)[@intCast(op.offset)..][0..@intCast(op.size)];
            benchmarkHostMemoryFill(bytes, op.data);
        },
        .update_buffer => |op| {
            const destination = bufferBytes(op.dst)[@intCast(op.offset)..][0..op.data.len];
            benchmarkHostMemoryCopy(destination, op.data);
        },
        .copy_buffer => |op| {
            const src = bufferBytes(op.src)[@intCast(op.region.src_offset)..][0..@intCast(op.region.size)];
            const dst = bufferBytes(op.dst)[@intCast(op.region.dst_offset)..][0..@intCast(op.region.size)];
            benchmarkHostMemoryCopy(dst, src);
        },
        .clear => |op| {
            const pattern: u32 = @bitCast(op.color);
            const bytes = imageBytes(op.image);
            const layer_size: usize = @intCast(imageLayerByteSize(op.image).?);
            const start: usize = @intCast(imageLayerOffset(op.image, op.base_layer).?);
            fillImagePattern(bytes[start..][0 .. layer_size * op.layer_count], pattern);
            op.image.clear_pattern = pattern;
            op.image.content_bounds = emptyRect();
            op.image.force_full_present = true;
            op.image.complex_3d_content = false;
        },
        .clear_depth => |op| {
            const pattern: u32 = @bitCast(op.depth);
            const bytes = imageBytes(op.image);
            const layer_size: usize = @intCast(imageLayerByteSize(op.image).?);
            const start: usize = @intCast(imageLayerOffset(op.image, op.base_layer).?);
            fillImagePattern(bytes[start..][0 .. layer_size * op.layer_count], pattern);
            op.image.clear_pattern = pattern;
            op.image.content_bounds = emptyRect();
            op.image.force_full_present = true;
            op.image.complex_3d_content = false;
        },
        .dispatch => |op| executeComputeDispatch(op),
        .dispatch_indirect => |op| {
            const bytes = bufferBytes(op.buffer);
            const groups = .{ std.mem.readInt(u32, bytes[@intCast(op.offset)..][0..4], .little), std.mem.readInt(u32, bytes[@intCast(op.offset + 4)..][0..4], .little), std.mem.readInt(u32, bytes[@intCast(op.offset + 8)..][0..4], .little) };
            if (dispatchGroupsValid(groups)) executeComputeDispatch(.{ .base = .{ 0, 0, 0 }, .groups = groups, .pipeline = op.pipeline, .layout = op.layout, .descriptors = op.descriptors });
        },
        .render_clear => |op| {
            const operation_start = frame_pacing.monotonicNs();
            const full_color_clear = op.color_base_layer == 0 and op.layer_count == op.image.array_layers;
            const full_depth_clear = if (op.depth) |depth| op.depth_base_layer == 0 and op.layer_count == depth.array_layers else true;
            if (!full_color_clear or !full_depth_clear) {
                const color_pattern: u32 = @bitCast(op.color);
                const depth_pattern: u32 = @bitCast(op.depth_value);
                for (0..op.layer_count) |layer| {
                    const index: u32 = @intCast(layer);
                    if (op.clear_color) fillImagePattern(imageLayerBytes(op.image, op.color_base_layer + index), color_pattern);
                    if (op.depth) |depth| {
                        if (op.clear_depth) fillImagePattern(imageLayerBytes(depth, op.depth_base_layer + index), depth_pattern);
                    }
                }
                if (op.clear_color) {
                    op.image.clear_pattern = color_pattern;
                    op.image.content_bounds = emptyRect();
                    op.image.force_full_present = true;
                    op.image.complex_3d_content = false;
                }
                if (op.depth) |depth| {
                    if (op.clear_depth) {
                        depth.clear_pattern = depth_pattern;
                        depth.content_bounds = emptyRect();
                    }
                }
                op.image.last_clear_ns = frame_pacing.monotonicNs() - operation_start;
                return;
            }
            const bytes = imageBytes(op.image);
            if (op.depth) |depth| {
                const depth_bytes = imageBytes(depth);
                const color_pattern: u32 = @bitCast(op.color);
                const depth_pattern: u32 = @bitCast(op.depth_value);
                const sparse = op.clear_color and op.clear_depth and bytes.len >= 8 * 1024 * 1024 and op.image.width == depth.width and op.image.height == depth.height and op.image.clear_pattern == color_pattern and depth.clear_pattern == depth_pattern and depth.memory != null and !depth.memory.?.mapped;
                if (op.clear_color and op.clear_depth) {
                    if (sparse) {
                        if (op.image.dirty_tiles) |tiles| {
                            if (!cpu_cube.clearDirtyTilesParallel(bytes, color_pattern, depth_bytes, depth_pattern, op.image.width, op.image.height, tiles)) {
