            for (op.pool.slots[op.first .. op.first + op.count], 0..) |*slot, index| {
                if (op.flags & 2 != 0) while (slot.state.load(.acquire) != 2) frame_pacing.sleepUntil(frame_pacing.monotonicNs() + 50_000);
