fn buildComputePipelineLocked(d: Device, ci: *const ComputePipelineCreateInfo) CanonicalError!ComputePipelineObj {
    const effective_flags = pipelineCreateFlags2(ci.p_next, ci.flags, true) orelse return error.Invalid;
    if (ci.s_type != 29 or ci.base_pipeline != 0 or (ci.base_pipeline_index != -1 and ci.base_pipeline_index != 0)) return error.Invalid;
    const layout = validPipelineLayoutLocked(ci.layout) orelse return error.Invalid;
    if (!layout.owner.eql(d)) return error.Invalid;
    const stage = ci.stage;
    if (stage.s_type != 18 or !pipelineRobustnessCreateInfoValid(stage.p_next) or stage.flags != 0 or stage.stage != 32 or stage.name == null) return error.Invalid;
    const shader = findLiveHandle(ShaderModuleObj, stage.module, &shader_module_objects, &shader_module_state) orelse return error.Invalid;
    if (!shader.owner.eql(d)) return error.Invalid;
    const name = std.mem.span(stage.name.?);
    if (name.len == 0 or name.len > 255) return error.Invalid;

    var w: CanonicalWriter = .{};
    defer w.deinit();
    try w.header(6);
    try w.u32le(effective_flags);
    try w.u32le(stage.stage);
    try w.u32le(shader.module.identity.ingestion);
    try w.u32le(shader.module.identity.serialization);
    try w.raw(&shader.module.identity.digest);
    try w.u64le(shader.module.words.len);
    for (shader.module.words) |word| try w.u32le(word);
    try w.u32le(@intCast(name.len));
    try w.raw(name);
    try appendSpecialization(&w, stage.specialization_info);
    try appendCanonical(&w, &layout.canonical);
    var canonical = try w.done();
    errdefer canonical.deinit();
    var layout_identity = try layout.canonical.clone();
    errdefer layout_identity.deinit();
    var frontend_specs: [64]spirv_frontend.Specialization = undefined;
    var frontend_spec_count: usize = 0;
    if (stage.specialization_info) |specialization| {
        const entries = if (specialization.map_entries) |p| p[0..specialization.map_entry_count] else &.{};
        const data: [*]const u8 = if (specialization.data) |p| @ptrCast(p) else @ptrFromInt(1);
        for (entries) |entry| {
            frontend_specs[frontend_spec_count] = .{ .id = entry.constant_id, .bytes = data[entry.offset..][0..entry.size] };
            frontend_spec_count += 1;
        }
    }
    var program = spirv_frontend.compile(allocator, shader.module.words, .compute, name, frontend_specs[0..frontend_spec_count]) catch |err| switch (err) {
        error.OutOfMemory => return error.OutOfMemory,
        else => return error.Invalid,
    };
    const executor = render_ir_exec.Executor.init(allocator, &program) catch |err| {
        program.deinit(allocator);
        return switch (err) {
            error.OutOfMemory => error.OutOfMemory,
            else => error.Invalid,
        };
    };
    program.deinit(allocator);
    return .{ .owner = DeviceIdentity.capture(d), .canonical = canonical, .layout = layout_identity, .executor = executor, .dispatch_base = effective_flags & pipeline_create_dispatch_base_bit != 0 };
}

fn validViewportDomain(viewport: Viewport) bool {
    const max_extent = @as(f32, @floatFromInt(max_2d_extent));
    return std.math.isFinite(viewport.x) and std.math.isFinite(viewport.y) and std.math.isFinite(viewport.width) and std.math.isFinite(viewport.height) and std.math.isFinite(viewport.min_depth) and std.math.isFinite(viewport.max_depth) and viewport.width != 0 and viewport.height != 0 and viewport.x >= -32_768 and viewport.x <= 32_767 and viewport.y >= -32_768 and viewport.y <= 32_767 and @abs(viewport.width) <= max_extent and @abs(viewport.height) <= max_extent and viewport.min_depth >= 0 and viewport.min_depth <= 1 and viewport.max_depth >= 0 and viewport.max_depth <= 1 and viewport.min_depth <= viewport.max_depth;
}
fn validScissorDomain(scissor: Rect2D) bool {
    return scissor.extent.width <= max_2d_extent and scissor.extent.height <= max_2d_extent;
}

fn buildGraphicsPipelineLocked(d: Device, ci: *const GraphicsPipelineCreateInfo) CanonicalError!GraphicsPipelineObj {
    const pnext = graphicsPipelinePNext(ci.p_next, ci.flags) orelse return error.Invalid;
    if (ci.s_type != 28 or ci.stage_count != 2 or ci.stages == null or ci.tessellation != null or ci.base_pipeline != 0 or (ci.base_pipeline_index != -1 and ci.base_pipeline_index != 0)) return error.Invalid;
    const layout = validPipelineLayoutLocked(ci.layout) orelse return error.Invalid;
    const dynamic_rendering_state = pnext.rendering;
    if (dynamic_rendering_state != null and ci.render_pass != 0) return error.Invalid;
    if (dynamic_rendering_state != null and ci.subpass != 0) return error.Invalid;
    const render_pass = if (ci.render_pass != 0) validRenderPassLocked(ci.render_pass) else null;
    if (render_pass == null and dynamic_rendering_state == null) return error.Invalid;
    if (!layout.owner.eql(d) or (render_pass != null and !render_pass.?.owner.eql(d)) or (render_pass != null and ci.subpass >= render_pass.?.subpass_count)) return error.Invalid;
    var dynamic_render_compatibility: ?Canonical = null;
    if (dynamic_rendering_state) |state| {
        dynamic_render_compatibility = try pipelineRenderingCompatibility(state);
    }
    defer if (dynamic_render_compatibility) |*compatibility| compatibility.deinit();
    var w: CanonicalWriter = .{};
    defer w.deinit();
    try w.header(5);
    try w.u32le(1); // cpu_cube_v1
    try appendCanonical(&w, &layout.canonical);
    if (render_pass) |pass| {
        try appendCanonical(&w, &pass.compatibility);
    } else {
        try appendCanonical(&w, &dynamic_render_compatibility.?);
    }
    try w.u32le(ci.subpass);
    var stage_indices: [2]u8 = .{ 0, 1 };
    const stages = ci.stages.?[0..2];
    if (stages[1].stage < stages[0].stage) stage_indices = .{ 1, 0 };
    var stage_mask: u32 = 0;
    var vertex_program: ?render_ir.Program = null;
    errdefer if (vertex_program) |*program| program.deinit(allocator);
    var fragment_program: ?render_ir.Program = null;
    errdefer if (fragment_program) |*program| program.deinit(allocator);
    var cpu_cube_stage_mask: u32 = 0;
    for (stage_indices) |index| {
        const stage = stages[index];
        if (stage.s_type != 18 or !pipelineRobustnessCreateInfoValid(stage.p_next) or stage.flags != 0 or (stage.stage != 1 and stage.stage != 0x10) or stage_mask & stage.stage != 0 or stage.name == null) return error.Invalid;
        const shader = findLiveHandle(ShaderModuleObj, stage.module, &shader_module_objects, &shader_module_state) orelse return error.Invalid;
        if (!shader.owner.eql(d)) return error.Invalid;
        const name = std.mem.span(stage.name.?);
        if (name.len == 0 or name.len > 255) return error.Invalid;
        stage_mask |= stage.stage;
        try w.u32le(stage.stage);
        try w.u32le(shader.module.identity.ingestion);
        try w.u32le(shader.module.identity.serialization);
        try w.raw(&shader.module.identity.digest);
        try w.u64le(shader.module.words.len);
        for (shader.module.words) |word| try w.u32le(word);
        try w.u32le(@intCast(name.len));
        try w.raw(name);
        try appendSpecialization(&w, stage.specialization_info);
        var frontend_specs: [64]spirv_frontend.Specialization = undefined;
        var frontend_spec_count: usize = 0;
        if (stage.specialization_info) |specialization| {
            const entries = if (specialization.map_entries) |p| p[0..specialization.map_entry_count] else &.{};
            const data: [*]const u8 = if (specialization.data) |p| @ptrCast(p) else @ptrFromInt(1);
            for (entries) |entry| {
                frontend_specs[frontend_spec_count] = .{ .id = entry.constant_id, .bytes = data[entry.offset..][0..entry.size] };
                frontend_spec_count += 1;
            }
        }
        const frontend_stage: render_ir.Stage = if (stage.stage == 1) .vertex else .fragment;
        const compiled = try compileFrontendStage(allocator, shader, frontend_stage, name, frontend_specs[0..frontend_spec_count]);
        if (compiled == null) cpu_cube_stage_mask |= stage.stage;
        if (compiled) |program| {
            if (frontend_stage == .vertex) vertex_program = program else fragment_program = program;
        }
    }
    if (stage_mask != 0x11) return error.Invalid;
    const profile_pair = vertex_program != null and fragment_program != null and cpu_cube_stage_mask == 0;
    const cpu_cube_pair = vertex_program == null and fragment_program == null and cpu_cube_stage_mask == 0x11;
    if (!profile_pair and !cpu_cube_pair) return error.Invalid;
    if (profile_pair and !frontendInterfacesCompatible(&vertex_program.?, &fragment_program.?, &layout.set0)) return error.Invalid;
    const vi = ci.vertex_input orelse return error.Invalid;
    if (vi.s_type != 19 or vi.p_next != null or vi.flags != 0 or vi.binding_count > 16 or vi.attribute_count > 16 or (vi.binding_count != 0 and vi.bindings == null) or (vi.attribute_count != 0 and vi.attributes == null)) return error.Invalid;
    var binding_indices: [16]u8 = undefined;
    for (0..vi.binding_count) |i| binding_indices[i] = @intCast(i);
    const bindings = if (vi.bindings) |p| p[0..vi.binding_count] else &.{};
    std.mem.sort(u8, binding_indices[0..vi.binding_count], bindings, struct {
        fn less(items: []const VertexInputBindingDescription, a: u8, b: u8) bool {
            return items[a].binding < items[b].binding;
        }
    }.less);
    try w.u32le(vi.binding_count);
    var prior_binding: ?u32 = null;
    for (binding_indices[0..vi.binding_count]) |index| {
        const b = bindings[index];
        if (prior_binding == b.binding or b.binding >= 16 or b.stride > 2048 or b.input_rate < 0 or b.input_rate > 1) return error.Invalid;
        prior_binding = b.binding;
        try w.u32le(b.binding);
        try w.u32le(b.stride);
        try w.i32le(b.input_rate);
    }
    var attribute_indices: [32]u8 = undefined;
    for (0..vi.attribute_count) |i| attribute_indices[i] = @intCast(i);
    const attributes = if (vi.attributes) |p| p[0..vi.attribute_count] else &.{};
    std.mem.sort(u8, attribute_indices[0..vi.attribute_count], attributes, struct {
        fn less(items: []const VertexInputAttributeDescription, a: u8, b: u8) bool {
            return items[a].location < items[b].location;
        }
    }.less);
    try w.u32le(vi.attribute_count);
    var prior_location: ?u32 = null;
    var vertex_input_binding_mask: u16 = 0;
    for (attribute_indices[0..vi.attribute_count]) |index| {
        const a = attributes[index];
        if (prior_location == a.location or a.location >= 16 or a.offset > 2047 or a.format <= 0) return error.Invalid;
        prior_location = a.location;
        var found = false;
        for (bindings) |b| if (b.binding == a.binding) {
            found = true;
            break;
        };
        if (!found) return error.Invalid;
        vertex_input_binding_mask |= @as(u16, 1) << @intCast(a.binding);
        try w.u32le(a.location);
        try w.u32le(a.binding);
        try w.i32le(a.format);
        try w.u32le(a.offset);
    }
    const profile_contract = if (profile_pair) profileGraphicsContract(&vertex_program.?, &fragment_program.?, vi) else null;
    const ia = ci.input_assembly orelse return error.Invalid;
    if (ia.s_type != 20 or ia.p_next != null or ia.flags != 0 or ia.topology < 0 or ia.topology > 10) return error.Invalid;
    try w.i32le(ia.topology);
    var dynamic_viewport = false;
    var dynamic_scissor = false;
    var dynamic_cull_mode = false;
    var dynamic_front_face = false;
    var dynamic_primitive_topology = false;
    var dynamic_primitive_restart_enable = false;
