    for (&pipeline_cache_objects, &pipeline_cache_state) |*cache, *state| if (state.* == .never) {
        cache.* = .{ .owner = DeviceIdentity.capture(d), .data = owned_payload };
        state.* = .live;
        out.* = @intFromPtr(cache);
