    lock();
    const d = device orelse {
        mutex.unlock();
        return .error_initialization_failed;
    };
    if (!validDeviceLocked(d)) {
        mutex.unlock();
        return .error_initialization_failed;
    }
    for (wait.semaphores.?[0..wait.semaphore_count], wait.values.?[0..wait.semaphore_count], 0..) |handle, value, index| {
