test "draw raster state selects baked and dynamic viewport scissor without allocation" {
    const baked_viewport = Viewport{ .x = 1, .y = 2, .width = 640, .height = 480, .min_depth = 0.125, .max_depth = 0.875 };
    const baked_scissor = cpu_cube.Rect{ .x = 3, .y = 4, .width = 600, .height = 440 };
    const dynamic_viewport = Viewport{ .x = 5, .y = 6, .width = 320, .height = 240, .min_depth = 0.25, .max_depth = 0.75 };
    const dynamic_scissor = cpu_cube.Rect{ .x = 7, .y = 8, .width = 300, .height = 220 };
    var pipeline: GraphicsPipelineObj = undefined;
    pipeline.viewport = baked_viewport;
    pipeline.scissor = baked_scissor;
    pipeline.cull_mode = 2;
    pipeline.front_face = 0;
    pipeline.primitive_topology = 3;
    pipeline.primitive_restart_enable = 0;
    pipeline.rasterizer_discard_enable = 0;
    pipeline.depth_test_enable = 1;
    pipeline.depth_write_enable = 1;
    pipeline.depth_compare_op = 3;
    pipeline.depth_bounds_test_enable = 1;
    pipeline.depth_bounds = .{ 0, 1 };
    pipeline.stencil_test_enable = 0;
    pipeline.depth_bias_enable = 0;
    pipeline.vertex_input_binding_mask = 0;
    pipeline.dynamic_cull_mode = false;
    pipeline.dynamic_front_face = false;
    pipeline.dynamic_primitive_topology = false;
    pipeline.dynamic_primitive_restart_enable = false;
    pipeline.dynamic_rasterizer_discard_enable = false;
    pipeline.dynamic_depth_test_enable = false;
    pipeline.dynamic_depth_write_enable = false;
    pipeline.dynamic_depth_compare_op = false;
    pipeline.dynamic_depth_bounds = false;
    pipeline.dynamic_depth_bounds_test_enable = false;
    pipeline.dynamic_stencil_test_enable = false;
    pipeline.dynamic_stencil_op = false;
    pipeline.dynamic_depth_bias_enable = false;
    pipeline.dynamic_vertex_input_binding_stride = false;
    pipeline.dynamic_line_width = false;
    pipeline.dynamic_line_stipple = false;
    pipeline.dynamic_depth_bias = false;
    pipeline.dynamic_blend_constants = false;
    pipeline.dynamic_stencil_compare_mask = false;
    pipeline.dynamic_stencil_write_mask = false;
    pipeline.dynamic_stencil_reference = false;
    var impl: CommandBufferImpl = undefined;
    impl.viewport = dynamic_viewport;
    impl.scissor = dynamic_scissor;
    impl.viewport_set = true;
    impl.scissor_set = true;
    impl.vertex_bindings = .{};
    impl.line_stipple_set = false;
    impl.dynamic.rasterizer_discard_enable_set = false;
    impl.dynamic.depth_test_enable_set = false;
    impl.dynamic.depth_write_enable_set = false;
    impl.dynamic.depth_compare_op_set = false;
    var command_buffer = CommandBufferObj{ .loader_data = 0, .impl = &impl };

    try std.testing.expect(validViewportDomain(baked_viewport));
    var invalid_viewport = baked_viewport;
    invalid_viewport.width = std.math.nan(f32);
    try std.testing.expect(!validViewportDomain(invalid_viewport));
    invalid_viewport = baked_viewport;
    invalid_viewport.height = 0;
    try std.testing.expect(!validViewportDomain(invalid_viewport));
    invalid_viewport = baked_viewport;
    invalid_viewport.width = 8193;
    try std.testing.expect(!validViewportDomain(invalid_viewport));
    try std.testing.expect(validScissorDomain(.{ .offset = .{ .x = 0, .y = 0 }, .extent = .{ .width = 8192, .height = 8192 } }));
    try std.testing.expect(!validScissorDomain(.{ .offset = .{ .x = 0, .y = 0 }, .extent = .{ .width = 8193, .height = 1 } }));

    pipeline.dynamic_viewport = false;
    pipeline.dynamic_scissor = false;
    var resolved = drawRasterState(&command_buffer, &pipeline).?;
    try std.testing.expectEqual(baked_viewport, resolved.viewport);
    try std.testing.expectEqual(baked_scissor, resolved.scissor);
    try std.testing.expectEqual(@as(u32, 2), resolved.cull_mode);
    try std.testing.expectEqual(@as(i32, 0), resolved.front_face);
    try std.testing.expectEqual(@as(i32, 3), resolved.primitive_topology);
    try std.testing.expectEqual(@as(u32, 0), resolved.primitive_restart_enable);
    try std.testing.expectEqual(@as(u32, 0), resolved.rasterizer_discard_enable);
    try std.testing.expectEqual(@as(u32, 1), resolved.depth_test_enable);
    try std.testing.expectEqual(@as(u32, 1), resolved.depth_write_enable);
    try std.testing.expectEqual(@as(i32, 3), resolved.depth_compare_op);
    try std.testing.expectEqual(@as(u32, 1), resolved.depth_bounds_test_enable);
    try std.testing.expectEqual([2]f32{ 0, 1 }, resolved.depth_bounds);

    pipeline.dynamic_viewport = true;
    pipeline.dynamic_scissor = true;
    impl.viewport_set = false;
    try std.testing.expect(drawRasterState(&command_buffer, &pipeline) == null);
    impl.viewport_set = true;
    impl.scissor_set = false;
    try std.testing.expect(drawRasterState(&command_buffer, &pipeline) == null);
    impl.scissor_set = true;
    impl.dynamic.cull_mode = 1;
    impl.dynamic.front_face = 1;
    resolved = drawRasterState(&command_buffer, &pipeline).?;
    try std.testing.expectEqual(dynamic_viewport, resolved.viewport);
    try std.testing.expectEqual(dynamic_scissor, resolved.scissor);
    try std.testing.expectEqual(@as(u32, 2), resolved.cull_mode);
    try std.testing.expectEqual(@as(i32, 0), resolved.front_face);

    pipeline.dynamic_cull_mode = true;
    pipeline.dynamic_front_face = true;
    resolved = drawRasterState(&command_buffer, &pipeline).?;
    try std.testing.expectEqual(@as(u32, 1), resolved.cull_mode);
    try std.testing.expectEqual(@as(i32, 1), resolved.front_face);
    impl.dynamic.cull_mode = std.math.maxInt(u32);
    try std.testing.expect(drawRasterState(&command_buffer, &pipeline) == null);
    impl.dynamic.cull_mode = 1;
    impl.dynamic.front_face = -1;
    try std.testing.expect(drawRasterState(&command_buffer, &pipeline) == null);
    impl.dynamic.front_face = 1;

    pipeline.dynamic_primitive_topology = true;
    pipeline.dynamic_primitive_restart_enable = true;
    try std.testing.expect(drawRasterState(&command_buffer, &pipeline) == null);
    impl.dynamic.primitive_topology = 3;
    impl.dynamic.primitive_topology_set = true;
    impl.dynamic.primitive_restart_enable = 0;
    impl.dynamic.primitive_restart_enable_set = true;
    resolved = drawRasterState(&command_buffer, &pipeline).?;
    try std.testing.expectEqual(@as(i32, 3), resolved.primitive_topology);
    try std.testing.expectEqual(@as(u32, 0), resolved.primitive_restart_enable);
    impl.dynamic.primitive_topology = 4;
    try std.testing.expect(drawRasterState(&command_buffer, &pipeline) == null);
    impl.dynamic.primitive_topology = 3;
    impl.dynamic.primitive_restart_enable = 1;
    try std.testing.expect(drawRasterState(&command_buffer, &pipeline) == null);
    impl.dynamic.primitive_restart_enable = 0;

    pipeline.dynamic_viewport = false;
    pipeline.dynamic_cull_mode = false;
    pipeline.dynamic_front_face = false;
    pipeline.dynamic_primitive_topology = false;
    pipeline.dynamic_primitive_restart_enable = false;
    pipeline.dynamic_rasterizer_discard_enable = true;
    try std.testing.expect(drawRasterState(&command_buffer, &pipeline) == null);
    impl.dynamic.rasterizer_discard_enable = 1;
    impl.dynamic.rasterizer_discard_enable_set = true;
    resolved = drawRasterState(&command_buffer, &pipeline).?;
    try std.testing.expectEqual(@as(u32, 1), resolved.rasterizer_discard_enable);
    impl.dynamic.rasterizer_discard_enable = 0;

    pipeline.dynamic_rasterizer_discard_enable = false;
    pipeline.dynamic_depth_test_enable = true;
    pipeline.dynamic_depth_write_enable = true;
    pipeline.dynamic_depth_compare_op = true;
    try std.testing.expect(drawRasterState(&command_buffer, &pipeline) == null);
    impl.dynamic.depth_test_enable = 0;
    impl.dynamic.depth_test_enable_set = true;
    impl.dynamic.depth_write_enable = 0;
    impl.dynamic.depth_write_enable_set = true;
    impl.dynamic.depth_compare_op = 7;
    impl.dynamic.depth_compare_op_set = true;
    resolved = drawRasterState(&command_buffer, &pipeline).?;
    try std.testing.expectEqual(@as(u32, 0), resolved.depth_test_enable);
    try std.testing.expectEqual(@as(u32, 0), resolved.depth_write_enable);
    try std.testing.expectEqual(@as(i32, 7), resolved.depth_compare_op);
    pipeline.dynamic_depth_test_enable = false;
    pipeline.dynamic_depth_write_enable = false;
    pipeline.dynamic_depth_compare_op = false;
    pipeline.dynamic_depth_bounds = true;
    try std.testing.expect(drawRasterState(&command_buffer, &pipeline) == null);
    impl.depth_bounds = .{ 0.25, 0.75 };
    impl.depth_bounds_set = true;
    resolved = drawRasterState(&command_buffer, &pipeline).?;
    try std.testing.expectEqual([2]f32{ 0.25, 0.75 }, resolved.depth_bounds);
    pipeline.dynamic_depth_bounds = false;
    pipeline.dynamic_depth_bounds_test_enable = true;
    try std.testing.expect(drawRasterState(&command_buffer, &pipeline) == null);
    impl.dynamic.depth_bounds_test_enable = 1;
    impl.dynamic.depth_bounds_test_enable_set = true;
    resolved = drawRasterState(&command_buffer, &pipeline).?;
    try std.testing.expectEqual(@as(u32, 1), resolved.depth_bounds_test_enable);
    pipeline.dynamic_stencil_test_enable = true;
    try std.testing.expect(drawRasterState(&command_buffer, &pipeline) == null);
    impl.dynamic.stencil_test_enable = 0;
    impl.dynamic.stencil_test_enable_set = true;
    resolved = drawRasterState(&command_buffer, &pipeline).?;
    pipeline.dynamic_stencil_test_enable = false;
    pipeline.dynamic_stencil_op = true;
    try std.testing.expect(drawRasterState(&command_buffer, &pipeline) == null);
    impl.dynamic.stencil_op_set = true;
    resolved = drawRasterState(&command_buffer, &pipeline).?;
    pipeline.dynamic_stencil_op = false;
    pipeline.dynamic_depth_bias_enable = true;
    try std.testing.expect(drawRasterState(&command_buffer, &pipeline) == null);
