fn queueWaitIdle(queue: ?Queue) callconv(.c) Result {
    const q = queue orelse return .error_initialization_failed;
    lock();
    if (!validDeviceLocked(q.owner)) {
        mutex.unlock();
        return .error_initialization_failed;
    }
    var owned: [8]*SwapchainObj = undefined;
    var count: usize = 0;
    for (&swapchain_objects, swapchain_state) |*swapchain, state| if (state == .live and swapchain.owner == q.owner) {
        owned[count] = swapchain;
        count += 1;
    };
    mutex.unlock();
    for (owned[0..count]) |swapchain| {
        _ = std.c.pthread_mutex_lock(&swapchain.present_mutex);
        while (swapchain.pending != 0) _ = std.c.pthread_cond_wait(&swapchain.present_condition, &swapchain.present_mutex);
        _ = std.c.pthread_mutex_unlock(&swapchain.present_mutex);
    }
    return .success;
}
const PresentTimingRequest = struct { target_ns: u64, requested_stages: u32, present_id: ?u64 = null };

fn presentTimingRequest(info: *const PresentInfo, index: usize, now_ns: u64) !?PresentTimingRequest {
    var next = info.p_next;
    var depth: usize = 0;
    var seen_timings = false;
    var seen_present_ids = false;
    var present_id: ?u64 = null;
    var request: ?PresentTimingRequest = null;
    while (next) |raw| : (depth += 1) {
        if (depth == 16) return error.InvalidPresentTiming;
        const header: *const ChainHeader = @ptrCast(@alignCast(raw));
        if (header.s_type == google_present_times_info_stype) {
            logGoogleDisplayTimingRejected("VkPresentTimesInfoGOOGLE in vkQueuePresentKHR");
            return error.GoogleDisplayTimingUnsupported;
        }
        if (header.s_type == 1_000_479_001) {
            if (seen_present_ids) return error.InvalidPresentTiming;
            seen_present_ids = true;
            const ids: *const PresentId2KHR = @ptrCast(@alignCast(raw));
            if (ids.p_next != null or ids.swapchain_count != info.swapchain_count or ids.present_ids == null) return error.InvalidPresentTiming;
            present_id = ids.present_ids.?[index];
            if (present_id.? == 0) return error.InvalidPresentTiming;
            if (request) |*value| value.present_id = present_id;
            next = @ptrCast(header.p_next);
            continue;
        }
        if (header.s_type == 1_000_208_003) {
            if (seen_timings) return error.InvalidPresentTiming;
            seen_timings = true;
            const timings: *const PresentTimingsInfoEXT = @ptrCast(@alignCast(raw));
            if (timings.swapchain_count != info.swapchain_count or timings.timing_infos == null) return error.InvalidPresentTiming;
            const timing = timings.timing_infos.?[index];
            if (timing.s_type != 1_000_208_004 or timing.p_next != null or timing.flags & ~@as(u32, 3) != 0 or timing.flags == 3 or timing.time_domain_id != 1 or timing.present_stage_queries & ~@as(u32, 0xf) != 0 or timing.target_time_domain_present_stage & ~@as(u32, 0xf) != 0) return error.InvalidPresentTiming;
            var target = if (timing.flags & 1 != 0) std.math.add(u64, now_ns, timing.target_time) catch return error.InvalidPresentTiming else timing.target_time;
            if (timing.flags & 2 != 0) {
                const rate = frame_pacing.configuredRate();
                const period = std.math.cast(u64, (@as(u128, frame_pacing.ns_per_second) * rate.denominator) / rate.numerator) orelse return error.InvalidPresentTiming;
                if (period == 0) return error.InvalidPresentTiming;
                const delta = target -| now_ns;
                const cycles = std.math.add(u64, delta, period / 2) catch return error.InvalidPresentTiming;
                const rounded = (cycles / period) * period;
                target = std.math.add(u64, now_ns, rounded) catch return error.InvalidPresentTiming;
            }
            request = .{ .target_ns = target, .requested_stages = timing.present_stage_queries, .present_id = present_id };
            next = @ptrCast(header.p_next);
            continue;
        }
        return error.InvalidPresentTiming;
    }
    return request;
}

fn presentTarget(info: *const PresentInfo, index: usize, now_ns: u64) !?u64 {
    return if (try presentTimingRequest(info, index, now_ns)) |request| request.target_ns else null;
}

fn recordPresentTiming(context: *anyopaque, timing: present_worker.Timing) void {
    const swapchain: *SwapchainObj = @ptrCast(@alignCast(context));
    _ = std.c.pthread_mutex_lock(&swapchain.present_mutex);
    defer _ = std.c.pthread_mutex_unlock(&swapchain.present_mutex);
    if (!timing.completed) {
        if (swapchain.present_timing_outstanding != 0) swapchain.present_timing_outstanding -= 1;
        return;
    }
    if (swapchain.present_timing_history_count >= max_present_entries) {
        if (swapchain.present_timing_outstanding != 0) swapchain.present_timing_outstanding -= 1;
        return;
    }
    const slot = swapchain.present_timing_history_count;
    swapchain.present_timing_history[slot] = .{
        .present_id = timing.present_id,
        .target_time = timing.target_time,
        .requested_stages = timing.requested_stages,
        .queue_operations_end_ns = timing.queue_operations_end_ns,
        .request_dequeued_ns = timing.request_dequeued_ns,
        .image_first_pixel_out_ns = timing.image_first_pixel_out_ns,
        .image_first_pixel_visible_ns = timing.image_first_pixel_visible_ns,
    };
    swapchain.present_timing_history_count += 1;
}

test "EXT present timing selects absolute and relative deadlines" {
    var timing = PresentTimingInfoEXT{ .s_type = 1_000_208_004, .p_next = null, .flags = 0, .target_time = 9_000, .time_domain_id = 1, .present_stage_queries = 0, .target_time_domain_present_stage = 0 };
    const timings = PresentTimingsInfoEXT{ .s_type = 1_000_208_003, .p_next = null, .swapchain_count = 1, .timing_infos = @ptrCast(&timing) };
    const info = PresentInfo{ .s_type = 1_000_001_001, .p_next = &timings, .wait_semaphore_count = 0, .wait_semaphores = null, .swapchain_count = 1, .swapchains = null, .image_indices = null, .results = null };
    try std.testing.expectEqual(@as(?u64, 9_000), try presentTarget(&info, 0, 1_000));
    timing.flags = 1;
    timing.target_time = 250;
    try std.testing.expectEqual(@as(?u64, 1_250), try presentTarget(&info, 0, 1_000));
    timing.time_domain_id = 2;
    try std.testing.expectError(error.InvalidPresentTiming, presentTarget(&info, 0, 1_000));
    timing.time_domain_id = 1;
    var duplicate_timings = timings;
    duplicate_timings.p_next = @ptrCast(&timings);
    var duplicate_info = info;
    duplicate_info.p_next = @ptrCast(&duplicate_timings);
    try std.testing.expectError(error.InvalidPresentTiming, presentTarget(&duplicate_info, 0, 1_000));
    const google = ChainHeader{ .s_type = google_present_times_info_stype, .p_next = null };
    var google_info = info;
    google_info.p_next = &google;
    try std.testing.expectError(error.GoogleDisplayTimingUnsupported, presentTarget(&google_info, 0, 1_000));
    const ignored = ChainHeader{ .s_type = 99, .p_next = null };
    var ignored_info = info;
    ignored_info.p_next = &ignored;
    try std.testing.expectError(error.InvalidPresentTiming, presentTarget(&ignored_info, 0, 1_000));
}

test "Google display timing procedure names are detected without aliases" {
    try std.testing.expect(googleDisplayTimingProc("vkGetRefreshCycleDurationGOOGLE"));
    try std.testing.expect(googleDisplayTimingProc("vkGetPastPresentationTimingGOOGLE"));
    try std.testing.expect(!googleDisplayTimingProc("vkGetSwapchainTimingPropertiesEXT"));
    try std.testing.expect(deviceLookup("vkGetRefreshCycleDurationGOOGLE") == null);
}

test "EXT present timing returned-only ABI and nearest-cycle targets are exact" {
    try std.testing.expectEqual(@as(usize, 16), @sizeOf(PresentStageTimeEXT));
    try std.testing.expectEqual(@as(usize, 72), @sizeOf(PastPresentationTimingEXT));
    try std.testing.expectEqual(@as(usize, 48), @sizeOf(PastPresentationTimingPropertiesEXT));
    try std.testing.expectEqual(@as(usize, 32), @sizeOf(PastPresentationTimingInfoEXT));
    try std.testing.expectEqual(@as(usize, 48), @sizeOf(PresentTimingInfoEXT));
    try std.testing.expectEqual(@as(usize, 32), @sizeOf(PresentTimingsInfoEXT));
    try std.testing.expectEqual(@as(usize, 32), @sizeOf(PresentId2KHR));
    var timing = PresentTimingInfoEXT{ .s_type = 1_000_208_004, .p_next = null, .flags = 2, .target_time = 10_000_000, .time_domain_id = 1, .present_stage_queries = 0, .target_time_domain_present_stage = 0 };
    var present_id: u64 = 42;
    var present_ids = PresentId2KHR{ .s_type = 1_000_479_001, .p_next = null, .swapchain_count = 1, .present_ids = @ptrCast(&present_id) };
    var timings = PresentTimingsInfoEXT{ .s_type = 1_000_208_003, .p_next = @ptrCast(&present_ids), .swapchain_count = 1, .timing_infos = @ptrCast(&timing) };
    const info = PresentInfo{ .s_type = 1_000_001_001, .p_next = &timings, .wait_semaphore_count = 0, .wait_semaphores = null, .swapchain_count = 1, .swapchains = null, .image_indices = null, .results = null };
    const identified = try presentTimingRequest(&info, 0, 1_000);
    try std.testing.expectEqual(@as(?u64, 42), identified.?.present_id);
    const nearest = try presentTarget(&info, 0, 1_000);
    try std.testing.expect(nearest.? >= 1_000);
    try std.testing.expectEqual(@as(u64, 8_334_333), nearest.?);
}

fn getSwapchainTimingProperties(device: ?Device, handle: usize, output: ?*SwapchainTimingPropertiesEXT, counter: ?*u64) callconv(.c) Result {
    lock();
    defer mutex.unlock();
    const swapchain = validSwapchainLocked(handle) orelse return .error_initialization_failed;
    const d = device orelse return .error_initialization_failed;
    if (!validDeviceLocked(d) or swapchain.owner != d) return .error_initialization_failed;
    const properties = output orelse return .error_initialization_failed;
    if (properties.s_type != 1_000_208_001 or properties.p_next != null) return .error_initialization_failed;
    const rate = frame_pacing.configuredRate();
    const duration = std.math.cast(u64, (@as(u128, frame_pacing.ns_per_second) * rate.denominator) / rate.numerator) orelse return .error_initialization_failed;
    properties.refresh_duration = duration;
    // ZPU exposes a fixed-refresh-rate presentation engine.  Vulkan defines
    // FRR by making refreshInterval equal to refreshDuration.
    properties.refresh_interval = duration;
    if (counter) |value| value.* = 1;
    return .success;
}

fn getSwapchainTimeDomainProperties(device: ?Device, handle: usize, output: ?*SwapchainTimeDomainPropertiesEXT, counter: ?*u64) callconv(.c) Result {
    lock();
    defer mutex.unlock();
    const swapchain = validSwapchainLocked(handle) orelse return .error_initialization_failed;
    const d = device orelse return .error_initialization_failed;
    if (!validDeviceLocked(d) or swapchain.owner != d) return .error_initialization_failed;
    const properties = output orelse return .error_initialization_failed;
    if (properties.s_type != 1_000_208_002 or properties.p_next != null) return .error_initialization_failed;
    const has_domains = properties.time_domains != null;
    const has_ids = properties.time_domain_ids != null;
    if (has_domains != has_ids) return .error_initialization_failed;
    if (has_domains and properties.time_domain_count == 0) return .error_initialization_failed;
    if (has_domains) {
        properties.time_domains.?[0] = 1_000_208_000;
        properties.time_domain_ids.?[0] = 1;
    }
    properties.time_domain_count = 1;
    if (counter) |value| value.* = 1;
    return .success;
}

fn setSwapchainPresentTimingQueueSize(device: ?Device, handle: usize, size: u32) callconv(.c) Result {
    lock();
    defer mutex.unlock();
    const swapchain = validSwapchainLocked(handle) orelse return .error_initialization_failed;
    const d = device orelse return .error_initialization_failed;
    if (!validDeviceLocked(d) or swapchain.owner != d) return .error_initialization_failed;
    if (!swapchain.present_timing_enabled) return .error_initialization_failed;
    if (size > max_present_entries) return .error_initialization_failed;
    if (size < swapchain.present_timing_outstanding) return .not_ready;
    swapchain.present_timing_queue_size = size;
    return .success;
}

fn getPastPresentationTiming(device: ?Device, info: ?*const PastPresentationTimingInfoEXT, output: ?*PastPresentationTimingPropertiesEXT) callconv(.c) Result {
    lock();
    defer mutex.unlock();
    const query = info orelse return .error_initialization_failed;
    const properties = output orelse return .error_initialization_failed;
    const swapchain = validSwapchainLocked(query.swapchain) orelse return .error_initialization_failed;
    const d = device orelse return .error_initialization_failed;
    if (!validDeviceLocked(d) or swapchain.owner != d or query.s_type != 1_000_208_005 or query.p_next != null or query.flags & ~@as(u32, 3) != 0 or properties.s_type != 1_000_208_006 or properties.p_next != null) return .error_initialization_failed;
    _ = std.c.pthread_mutex_lock(&swapchain.present_mutex);
    defer _ = std.c.pthread_mutex_unlock(&swapchain.present_mutex);
    const available = swapchain.present_timing_history_count;
    if (available == 0) {
        properties.timing_properties_counter = 1;
        properties.time_domains_counter = 1;
        properties.presentation_timing_count = 0;
        properties.presentation_timings = null;
        return .success;
    }
    const output_count = properties.presentation_timing_count;
    const outputs = properties.presentation_timings orelse {
        if (output_count != 0) return .error_initialization_failed;
        properties.timing_properties_counter = 1;
        properties.time_domains_counter = 1;
        properties.presentation_timing_count = available;
        return .success;
    };
    if (output_count == 0) return .error_initialization_failed;
    const write_count = @min(available, output_count);
    for (0..write_count) |index| {
        const timing_record = swapchain.present_timing_history[index];
        const destination = &outputs[index];
        const stage_pointer = destination.present_stages;
        destination.* = .{
            .s_type = 1_000_208_007,
            .p_next = null,
            .present_id = timing_record.present_id,
            .target_time = timing_record.target_time,
            .present_stage_count = @popCount(timing_record.requested_stages),
            .present_stages = stage_pointer,
            .time_domain = 1_000_208_000,
            .time_domain_id = 1,
            .report_complete = if (timing_record.requested_stages == 0 or stage_pointer != null) 1 else 0,
        };
        if (stage_pointer) |stages| {
            var written: usize = 0;
            const times = [_]u64{ timing_record.queue_operations_end_ns, timing_record.request_dequeued_ns, timing_record.image_first_pixel_out_ns, timing_record.image_first_pixel_visible_ns };
            inline for ([_]u32{ 1, 2, 4, 8 }, 0..) |bit, stage_index| {
                if (timing_record.requested_stages & bit != 0) {
                    stages[written] = .{ .stage = bit, .time = times[stage_index] };
                    written += 1;
                }
            }
        }
    }
    if (write_count != 0) {
        const remaining = available - write_count;
        if (remaining != 0) std.mem.copyForwards(PresentTimingRecord, swapchain.present_timing_history[0..remaining], swapchain.present_timing_history[write_count..available]);
        swapchain.present_timing_history_count = remaining;
        swapchain.present_timing_outstanding -= @intCast(write_count);
    }
    properties.timing_properties_counter = 1;
    properties.time_domains_counter = 1;
    properties.presentation_timing_count = write_count;
    properties.presentation_timings = outputs;
    return if (write_count < available) .incomplete else .success;
}

fn deviceWaitIdle(device: ?Device) callconv(.c) Result {
    const d = device orelse return .error_initialization_failed;
    lock();
    if (!validDeviceLocked(d)) {
        mutex.unlock();
        return .error_initialization_failed;
    }
    var queue: ?Queue = null;
    for (&device_objects, &queue_objects, device_state) |*candidate, *candidate_queue, state| if (state == .live and candidate == d) {
        queue = candidate_queue;
        break;
    };
    mutex.unlock();
    return queueWaitIdle(queue);
}

fn globalLookup(n: []const u8) Fn {
    const map = .{ .{ "vkGetInstanceProcAddr", getInstanceProcAddr }, .{ "vkCreateInstance", createInstance }, .{ "vkEnumerateInstanceVersion", enumerateInstanceVersion }, .{ "vkEnumerateInstanceExtensionProperties", enumerateInstanceExtensions }, .{ "vkEnumerateInstanceLayerProperties", enumerateInstanceLayers } };
    inline for (map) |e| if (std.mem.eql(u8, n, e[0])) return ptr(e[1]);
    return null;
}
fn instanceLookup(n: []const u8) Fn {
    if (globalLookup(n)) |f| return f;
    const map = .{ .{ "vkDestroyInstance", destroyInstance }, .{ "vkEnumeratePhysicalDevices", enumeratePhysicalDevices }, .{ "vkEnumeratePhysicalDeviceGroups", enumeratePhysicalDeviceGroups }, .{ "vkGetPhysicalDeviceFeatures", getFeatures }, .{ "vkGetPhysicalDeviceFeatures2", getPhysicalDeviceFeatures2 }, .{ "vkGetPhysicalDeviceProperties", getProperties }, .{ "vkGetPhysicalDeviceProperties2", getPhysicalDeviceProperties2 }, .{ "vkGetPhysicalDeviceQueueFamilyProperties", getQueueProperties }, .{ "vkGetPhysicalDeviceQueueFamilyProperties2", getPhysicalDeviceQueueFamilyProperties2 }, .{ "vkGetPhysicalDeviceMemoryProperties", getMemoryProperties }, .{ "vkGetPhysicalDeviceMemoryProperties2", getPhysicalDeviceMemoryProperties2 }, .{ "vkGetPhysicalDeviceFormatProperties", getFormatProperties }, .{ "vkGetPhysicalDeviceFormatProperties2", getPhysicalDeviceFormatProperties2 }, .{ "vkGetPhysicalDeviceImageFormatProperties", getImageFormatProperties }, .{ "vkGetPhysicalDeviceImageFormatProperties2", getPhysicalDeviceImageFormatProperties2 }, .{ "vkGetPhysicalDeviceSparseImageFormatProperties", getSparseImageFormatProperties }, .{ "vkGetPhysicalDeviceSparseImageFormatProperties2", getPhysicalDeviceSparseImageFormatProperties2 }, .{ "vkGetPhysicalDeviceToolProperties", getPhysicalDeviceToolProperties }, .{ "vkGetPhysicalDeviceExternalBufferProperties", getPhysicalDeviceExternalBufferProperties }, .{ "vkGetPhysicalDeviceExternalBufferPropertiesKHR", getPhysicalDeviceExternalBufferProperties }, .{ "vkGetPhysicalDeviceExternalFenceProperties", getPhysicalDeviceExternalFenceProperties }, .{ "vkGetPhysicalDeviceExternalSemaphoreProperties", getPhysicalDeviceExternalSemaphoreProperties }, .{ "vkGetPhysicalDeviceExternalSemaphorePropertiesKHR", getPhysicalDeviceExternalSemaphoreProperties }, .{ "vkEnumerateDeviceExtensionProperties", enumerateDeviceExtensions }, .{ "vkEnumerateDeviceLayerProperties", enumerateDeviceLayers }, .{ "vkCreateDevice", createDevice }, .{ "vkGetDeviceProcAddr", getDeviceProcAddr }, .{ "vkDestroyDevice", destroyDevice }, .{ "vkGetDeviceQueue", getDeviceQueue }, .{ "vkGetDeviceQueue2", getDeviceQueue2 }, .{ "vkCreateXcbSurfaceKHR", createXcbSurface }, .{ "vkCreateHeadlessSurfaceEXT", createHeadlessSurface }, .{ "vkDestroySurfaceKHR", destroySurface }, .{ "vkGetPhysicalDeviceSurfaceSupportKHR", getSurfaceSupport }, .{ "vkGetPhysicalDeviceSurfaceCapabilitiesKHR", getSurfaceCapabilities }, .{ "vkGetPhysicalDeviceSurfaceFormatsKHR", getSurfaceFormats }, .{ "vkGetPhysicalDeviceSurfacePresentModesKHR", getSurfacePresentModes } };
    inline for (map) |e| if (std.mem.eql(u8, n, e[0])) return ptr(e[1]);
    return deviceLookup(n);
}
fn deviceLookup(n: []const u8) Fn {
    if (googleDisplayTimingProc(n)) {
        logGoogleDisplayTimingRejected("device procedure lookup");
        return null;
    }
    const semaphore_commands = .{ .{ "vkGetSemaphoreCounterValue", getSemaphoreCounterValue }, .{ "vkSignalSemaphore", signalSemaphore }, .{ "vkWaitSemaphores", waitSemaphores } };
    inline for (semaphore_commands) |e| if (std.mem.eql(u8, n, e[0])) return ptr(e[1]);
    const compute_commands = .{ .{ "vkCmdDispatch", cmdDispatch }, .{ "vkCmdDispatchIndirect", cmdDispatchIndirect }, .{ "vkCmdDispatchBase", cmdDispatchBase }, .{ "vkCmdSetDeviceMask", cmdSetDeviceMask } };
    inline for (compute_commands) |e| if (std.mem.eql(u8, n, e[0])) return ptr(e[1]);
    const copy2_commands = .{ .{ "vkCmdCopyBuffer2", cmdCopyBuffer2 }, .{ "vkCmdCopyImage2", cmdCopyImage2 }, .{ "vkCmdBlitImage2", cmdBlitImage2 }, .{ "vkCmdResolveImage2", cmdResolveImage2 }, .{ "vkCmdCopyBufferToImage2", cmdCopyBufferToImage2 }, .{ "vkCmdCopyImageToBuffer2", cmdCopyImageToBuffer2 } };
    inline for (copy2_commands) |e| if (std.mem.eql(u8, n, e[0])) return ptr(e[1]);
    const sync2_commands = .{ .{ "vkCmdPipelineBarrier2", cmdPipelineBarrier2 }, .{ "vkCmdSetEvent2", cmdSetEvent2 }, .{ "vkCmdResetEvent2", cmdResetEvent2 }, .{ "vkCmdWaitEvents2", cmdWaitEvents2 }, .{ "vkCmdWriteTimestamp2", cmdWriteTimestamp2 } };
    inline for (sync2_commands) |e| if (std.mem.eql(u8, n, e[0])) return ptr(e[1]);
    const rendering_commands = .{ .{ "vkCmdBeginRendering", cmdBeginRendering }, .{ "vkCmdEndRendering", cmdEndRendering } };
    inline for (rendering_commands) |e| if (std.mem.eql(u8, n, e[0])) return ptr(e[1]);
    const device_group_commands = .{ .{ "vkGetDeviceGroupPeerMemoryFeatures", getDeviceGroupPeerMemoryFeatures }, .{ "vkCreateSamplerYcbcrConversion", createSamplerYcbcrConversion }, .{ "vkDestroySamplerYcbcrConversion", destroySamplerYcbcrConversion } };
    inline for (device_group_commands) |e| if (std.mem.eql(u8, n, e[0])) return ptr(e[1]);
    const maintenance4_commands = .{ .{ "vkCmdSetLineStipple", cmdSetLineStipple }, .{ "vkCmdBindIndexBuffer2", cmdBindIndexBuffer2 }, .{ "vkCmdBindVertexBuffers2", cmdBindVertexBuffers2 } };
    inline for (maintenance4_commands) |e| if (std.mem.eql(u8, n, e[0])) return ptr(e[1]);
    const maintenance6_commands = .{ .{ "vkCmdBindDescriptorSets2", cmdBindDescriptorSets2 }, .{ "vkCmdPushConstants2", cmdPushConstants2 }, .{ "vkCmdSetRenderingAttachmentLocations", cmdSetRenderingAttachmentLocations }, .{ "vkCmdSetRenderingInputAttachmentIndices", cmdSetRenderingInputAttachmentIndices } };
    inline for (maintenance6_commands) |e| if (std.mem.eql(u8, n, e[0])) return ptr(e[1]);
    const push_descriptor_commands = .{ .{ "vkCmdPushDescriptorSet", cmdPushDescriptorSet }, .{ "vkCmdPushDescriptorSet2", cmdPushDescriptorSet2 }, .{ "vkCmdPushDescriptorSetWithTemplate", cmdPushDescriptorSetWithTemplate }, .{ "vkCmdPushDescriptorSetWithTemplate2", cmdPushDescriptorSetWithTemplate2 } };
    inline for (push_descriptor_commands) |e| if (std.mem.eql(u8, n, e[0])) return ptr(e[1]);
    const map_memory2_commands = .{ .{ "vkMapMemory2", mapMemory2 }, .{ "vkUnmapMemory2", unmapMemory2 } };
    inline for (map_memory2_commands) |e| if (std.mem.eql(u8, n, e[0])) return ptr(e[1]);
    const host_copy_commands = .{ .{ "vkCopyMemoryToImage", copyMemoryToImage }, .{ "vkCopyImageToMemory", copyImageToMemory }, .{ "vkCopyImageToImage", copyImageToImage }, .{ "vkTransitionImageLayout", transitionImageLayout }, .{ "vkGetImageSubresourceLayout2", getImageSubresourceLayout2 }, .{ "vkGetDeviceImageSubresourceLayout", getDeviceImageSubresourceLayout }, .{ "vkGetRenderingAreaGranularity", getRenderingAreaGranularity } };
