pub export fn vk_icdNegotiateLoaderICDInterfaceVersion(version: ?*u32) callconv(.c) Result {
    const v = version orelse return .error_initialization_failed;
    v.* = @min(v.*, 7);
    return .success;
}
pub export fn vk_icdGetInstanceProcAddr(instance: ?Instance, name: ?[*:0]const u8) callconv(.c) Fn {
    return getInstanceProcAddr(instance, name);
}
pub export fn vk_icdGetPhysicalDeviceProcAddr(instance: ?Instance, name: ?[*:0]const u8) callconv(.c) Fn {
    lock();
    defer mutex.unlock();
    if (!validInstanceLocked(instance orelse return null)) return null;
    const n = std.mem.span(name orelse return null);
    const map = .{ .{ "vkGetPhysicalDeviceFeatures", getFeatures }, .{ "vkGetPhysicalDeviceFeatures2", getPhysicalDeviceFeatures2 }, .{ "vkGetPhysicalDeviceProperties", getProperties }, .{ "vkGetPhysicalDeviceProperties2", getPhysicalDeviceProperties2 }, .{ "vkGetPhysicalDeviceQueueFamilyProperties", getQueueProperties }, .{ "vkGetPhysicalDeviceQueueFamilyProperties2", getPhysicalDeviceQueueFamilyProperties2 }, .{ "vkGetPhysicalDeviceMemoryProperties", getMemoryProperties }, .{ "vkGetPhysicalDeviceMemoryProperties2", getPhysicalDeviceMemoryProperties2 }, .{ "vkGetPhysicalDeviceFormatProperties", getFormatProperties }, .{ "vkGetPhysicalDeviceFormatProperties2", getPhysicalDeviceFormatProperties2 }, .{ "vkGetPhysicalDeviceImageFormatProperties", getImageFormatProperties }, .{ "vkGetPhysicalDeviceImageFormatProperties2", getPhysicalDeviceImageFormatProperties2 }, .{ "vkGetPhysicalDeviceSparseImageFormatProperties", getSparseImageFormatProperties }, .{ "vkGetPhysicalDeviceSparseImageFormatProperties2", getPhysicalDeviceSparseImageFormatProperties2 }, .{ "vkGetPhysicalDeviceToolProperties", getPhysicalDeviceToolProperties }, .{ "vkGetPhysicalDeviceExternalBufferProperties", getPhysicalDeviceExternalBufferProperties }, .{ "vkGetPhysicalDeviceExternalBufferPropertiesKHR", getPhysicalDeviceExternalBufferProperties }, .{ "vkGetPhysicalDeviceExternalFenceProperties", getPhysicalDeviceExternalFenceProperties }, .{ "vkGetPhysicalDeviceExternalSemaphoreProperties", getPhysicalDeviceExternalSemaphoreProperties }, .{ "vkGetPhysicalDeviceExternalSemaphorePropertiesKHR", getPhysicalDeviceExternalSemaphoreProperties }, .{ "vkEnumerateDeviceExtensionProperties", enumerateDeviceExtensions }, .{ "vkEnumerateDeviceLayerProperties", enumerateDeviceLayers }, .{ "vkCreateDevice", createDevice }, .{ "vkGetPhysicalDeviceSurfaceSupportKHR", getSurfaceSupport }, .{ "vkGetPhysicalDeviceSurfaceCapabilitiesKHR", getSurfaceCapabilities }, .{ "vkGetPhysicalDeviceSurfaceFormatsKHR", getSurfaceFormats }, .{ "vkGetPhysicalDeviceSurfacePresentModesKHR", getSurfacePresentModes } };
    inline for (map) |e| if (std.mem.eql(u8, n, e[0])) return ptr(e[1]);
    return null;
}

test "negotiation and exact global lookup" {
    var v: u32 = 99;
    try std.testing.expectEqual(Result.success, vk_icdNegotiateLoaderICDInterfaceVersion(&v));
    try std.testing.expectEqual(@as(u32, 7), v);
    v = 3;
    try std.testing.expectEqual(Result.success, vk_icdNegotiateLoaderICDInterfaceVersion(&v));
    try std.testing.expectEqual(@as(u32, 3), v);
    try std.testing.expectEqual(Result.error_initialization_failed, vk_icdNegotiateLoaderICDInterfaceVersion(null));
    try std.testing.expect(vk_icdGetInstanceProcAddr(null, "vkCreateInstance") != null);
    try std.testing.expect(vk_icdGetInstanceProcAddr(null, "vkDestroyInstance") == null);
    try std.testing.expect(vk_icdGetInstanceProcAddr(null, "vkCreateInstanceX") == null);
    try std.testing.expect(vk_icdGetInstanceProcAddr(null, null) == null);
    try std.testing.expect(vk_icdGetInstanceProcAddr(@ptrFromInt(8), "vkDestroyInstance") == null);
    try std.testing.expectEqual(Result.error_initialization_failed, enumerateInstanceExtensions(null, null, null));
    for ([_][*:0]const u8{ "vkGetInstanceProcAddr", "vkCreateInstance", "vkEnumerateInstanceExtensionProperties", "vkEnumerateInstanceLayerProperties" }) |name| try std.testing.expect(vk_icdGetInstanceProcAddr(null, name) != null);
}
test "enumeration lifecycle and unsupported features" {
    var ci = InstanceInfo{ .s_type = 1, .p_next = null, .flags = 0, .app_info = null, .layer_count = 0, .layers = null, .extension_count = 0, .extensions = null };
    var instance: Instance = undefined;
    try std.testing.expectEqual(Result.success, createInstance(&ci, null, &instance));
    try std.testing.expectEqual(MAGIC, instance.loader_data);
    try std.testing.expect(vk_icdGetInstanceProcAddr(instance, "vkDestroyInstance") != null);
    try std.testing.expect(vk_icdGetPhysicalDeviceProcAddr(instance, "vkGetPhysicalDeviceProperties") != null);
    try std.testing.expect(vk_icdGetPhysicalDeviceProcAddr(instance, "vkDestroyInstance") == null);
    var extension_count: u32 = 9;
    try std.testing.expectEqual(Result.success, enumerateInstanceExtensions(null, &extension_count, null));
    try std.testing.expectEqual(@as(u32, 5), extension_count);
    var extension_properties: [5]ExtensionProperties = undefined;
    extension_count = 1;
    try std.testing.expectEqual(Result.incomplete, enumerateInstanceExtensions(null, &extension_count, &extension_properties));
    try std.testing.expectEqual(@as(u32, 1), extension_count);
    try std.testing.expectEqualStrings("VK_KHR_surface", std.mem.sliceTo(&extension_properties[0].name, 0));
    try std.testing.expectEqual(@as(u32, 25), extension_properties[0].spec_version);
    extension_count = 5;
    try std.testing.expectEqual(Result.success, enumerateInstanceExtensions(null, &extension_count, &extension_properties));
    try std.testing.expectEqualStrings("VK_KHR_xcb_surface", std.mem.sliceTo(&extension_properties[1].name, 0));
    try std.testing.expectEqual(@as(u32, 6), extension_properties[1].spec_version);
    try std.testing.expectEqualStrings("VK_EXT_headless_surface", std.mem.sliceTo(&extension_properties[2].name, 0));
    try std.testing.expectEqual(@as(u32, 1), extension_properties[2].spec_version);
    try std.testing.expectEqualStrings("VK_KHR_external_memory_capabilities", std.mem.sliceTo(&extension_properties[3].name, 0));
    try std.testing.expectEqual(@as(u32, 1), extension_properties[3].spec_version);
    try std.testing.expectEqualStrings("VK_KHR_external_semaphore_capabilities", std.mem.sliceTo(&extension_properties[4].name, 0));
    try std.testing.expectEqual(@as(u32, 1), extension_properties[4].spec_version);
    try std.testing.expect(vk_icdGetInstanceProcAddr(instance, "vkCreateHeadlessSurfaceEXT") != null);
    try std.testing.expect(vk_icdGetPhysicalDeviceProcAddr(instance, "vkGetPhysicalDeviceExternalBufferPropertiesKHR") != null);
    try std.testing.expect(vk_icdGetPhysicalDeviceProcAddr(instance, "vkGetPhysicalDeviceExternalSemaphorePropertiesKHR") != null);
    try std.testing.expectEqual(Result.error_extension_not_present, enumerateInstanceExtensions("layer", &extension_count, null));
    var count: u32 = 0;
    try std.testing.expectEqual(Result.success, enumeratePhysicalDevices(instance, &count, null));
    try std.testing.expectEqual(Result.error_initialization_failed, enumeratePhysicalDevices(instance, null, null));
    try std.testing.expectEqual(@as(u32, 1), count);
    var ps: [1]Physical = undefined;
    count = 0;
    try std.testing.expectEqual(Result.incomplete, enumeratePhysicalDevices(instance, &count, &ps));
    count = 1;
    try std.testing.expectEqual(Result.success, enumeratePhysicalDevices(instance, &count, &ps));
    var features = Features{ .values = [_]u32{0} ** 55 };
    features.values[0] = 1;
    var priority: f32 = 1;
    const qi = QueueInfo{ .s_type = 2, .p_next = null, .flags = 0, .family = 0, .count = 1, .priorities = @ptrCast(&priority) };
    var di = DeviceInfo{ .s_type = 3, .p_next = null, .flags = 0, .queue_info_count = 1, .queue_infos = @ptrCast(&qi), .layer_count = 0, .layers = null, .extension_count = 0, .extensions = null, .features = &features };
    var device: Device = undefined;
    try std.testing.expectEqual(Result.error_feature_not_present, createDevice(ps[0], &di, null, &device));
    di.features = null;
    try std.testing.expectEqual(Result.success, createDevice(ps[0], &di, null, &device));
    var queue: Queue = undefined;
    getDeviceQueue(device, 0, 0, &queue);
    try std.testing.expectEqual(MAGIC, queue.loader_data);
    for ([_][*:0]const u8{ "vkCmdBeginRenderPass2", "vkCmdNextSubpass2", "vkCmdEndRenderPass2", "vkGetBufferDeviceAddress", "vkGetBufferOpaqueCaptureAddress", "vkGetDeviceMemoryOpaqueCaptureAddress" }) |name| try std.testing.expect(getDeviceProcAddr(device, name) != null);
    destroyDevice(device, null);
    var feature2 = PhysicalDeviceFeatures2{ .s_type = 1000059000, .p_next = null, .features = std.mem.zeroes(Features) };
    di.p_next = @ptrCast(&feature2);
    try std.testing.expectEqual(Result.success, createDevice(ps[0], &di, null, &device));
    destroyDevice(device, null);
    feature2.features.values[0] = 1;
    try std.testing.expectEqual(Result.error_feature_not_present, createDevice(ps[0], &di, null, &device));
    feature2.features.values[0] = 0;
    var device_feature = PhysicalDevice16BitStorageFeatures{ .s_type = 1000083000, .p_next = null, .values = [_]u32{0} ** 4 };
    feature2.p_next = @ptrCast(&device_feature);
    try std.testing.expectEqual(Result.success, createDevice(ps[0], &di, null, &device));
    destroyDevice(device, null);
    device_feature.values[0] = 1;
    try std.testing.expectEqual(Result.error_feature_not_present, createDevice(ps[0], &di, null, &device));
    device_feature.values[0] = 0;
    feature2.p_next = null;
    const unsupported_device_chain = ChainHeader{ .s_type = 999, .p_next = null };
    di.p_next = @ptrCast(&unsupported_device_chain);
    try std.testing.expectEqual(Result.error_initialization_failed, createDevice(ps[0], &di, null, &device));
    di.p_next = null;
    try std.testing.expect(getDeviceProcAddr(device, "vkDestroyDevice") == null);
    try std.testing.expect(getDeviceProcAddr(@ptrFromInt(8), "vkDestroyDevice") == null);
    destroyInstance(instance, null);
    try std.testing.expect(vk_icdGetInstanceProcAddr(instance, "vkDestroyInstance") == null);
    const unsupported_extensions = [_][*:0]const u8{"VK_ZPU_unsupported"};
    ci.extension_count = 1;
    ci.extensions = &unsupported_extensions;
    try std.testing.expectEqual(Result.error_extension_not_present, createInstance(&ci, null, &instance));
    const supported_extensions = [_][*:0]const u8{ "VK_KHR_surface", "VK_KHR_xcb_surface", "VK_EXT_headless_surface", "VK_KHR_external_memory_capabilities", "VK_KHR_external_semaphore_capabilities" };
    ci.extension_count = supported_extensions.len;
    ci.extensions = &supported_extensions;
    try std.testing.expectEqual(Result.success, createInstance(&ci, null, &instance));
    destroyInstance(instance, null);
    ci.extension_count = 0;
    ci.extensions = null;
    const unsupported_chain = ChainHeader{ .s_type = 999, .p_next = null };
    ci.p_next = &unsupported_chain;
    try std.testing.expectEqual(Result.error_initialization_failed, createInstance(&ci, null, &instance));
}

test "core instance physical and device enumeration is bounded and allocation free" {
    try std.testing.expectEqual(@as(usize, 220), @sizeOf(Features));
    try std.testing.expectEqual(@as(usize, 24), @sizeOf(QueueProperties));
    try std.testing.expectEqual(@as(usize, 520), @sizeOf(MemoryProperties));
    const ci = InstanceInfo{ .s_type = 1, .p_next = null, .flags = 0, .app_info = null, .layer_count = 0, .layers = null, .extension_count = 0, .extensions = null };
    var instance: Instance = undefined;
    try std.testing.expectEqual(Result.success, createInstance(&ci, null, &instance));
    var physical_count: u32 = 1;
    var physical: [1]Physical = undefined;
    try std.testing.expectEqual(Result.success, enumeratePhysicalDevices(instance, &physical_count, &physical));
    var instance_extensions: [5]ExtensionProperties = undefined;
    var device_extensions: [2]ExtensionProperties = undefined;
    test_allocations_before_failure = 0;
    defer test_allocations_before_failure = null;
    for (0..4096) |_| {
        var count: u32 = 0;
        try std.testing.expectEqual(Result.success, enumerateInstanceExtensions(null, &count, null));
        try std.testing.expectEqual(@as(u32, 5), count);
        count = instance_extensions.len;
        try std.testing.expectEqual(Result.success, enumerateInstanceExtensions(null, &count, &instance_extensions));
        try std.testing.expectEqual(@as(u32, 5), count);
        count = 0;
        try std.testing.expectEqual(Result.success, enumeratePhysicalDevices(instance, &count, null));
        try std.testing.expectEqual(@as(u32, 1), count);
        count = physical.len;
        try std.testing.expectEqual(Result.success, enumeratePhysicalDevices(instance, &count, &physical));
        try std.testing.expectEqual(@as(u32, 1), count);
        count = 0;
        try std.testing.expectEqual(Result.success, enumerateDeviceExtensions(physical[0], null, &count, null));
        try std.testing.expectEqual(@as(u32, 2), count);
        count = device_extensions.len;
        try std.testing.expectEqual(Result.success, enumerateDeviceExtensions(physical[0], null, &count, &device_extensions));
        try std.testing.expectEqual(@as(u32, 2), count);
        var features = Features{ .values = [_]u32{1} ** 55 };
        getFeatures(physical[0], &features);
        try std.testing.expectEqualSlices(u32, &([_]u32{0} ** 55), &features.values);
        var sparse_count: u32 = 1;
        getSparseImageFormatProperties(physical[0], 37, 1, 1, 4, 0, &sparse_count, @ptrFromInt(8));
        try std.testing.expectEqual(@as(u32, 0), sparse_count);
        var queue_count: u32 = 1;
        var queue_properties: [1]QueueProperties = undefined;
        getQueueProperties(physical[0], &queue_count, &queue_properties);
        try std.testing.expectEqual(@as(u32, 1), queue_count);
        try std.testing.expectEqual(@as(u32, 0x7), queue_properties[0].flags);
        try std.testing.expectEqual(@as(u32, 64), queue_properties[0].timestamp_bits);
        var memory_properties: MemoryProperties = undefined;
        getMemoryProperties(physical[0], &memory_properties);
        try std.testing.expectEqual(@as(u32, 1), memory_properties.memory_type_count);
        try std.testing.expectEqual(@as(u32, 0x7), memory_properties.memory_types[0].property_flags);
        try std.testing.expectEqual(@as(u64, heap_size), memory_properties.memory_heaps[0].size);
        var format_properties: FormatProperties = undefined;
        getFormatProperties(physical[0], 44, &format_properties);
        try std.testing.expectEqual(@as(u32, 0xc080), format_properties.optimal_tiling_features);
        var image_format_properties: ImageFormatProperties = undefined;
        try std.testing.expectEqual(Result.success, getImageFormatProperties(physical[0], 44, 1, 0, 0x13, 0, &image_format_properties));
        try std.testing.expectEqual(@as(u32, 1), image_format_properties.sample_counts);
    }
    destroyInstance(instance, null);
}

test "XCB and headless surface lifecycle and physical presentation queries" {
    const extensions = [_][*:0]const u8{ "VK_KHR_surface", "VK_KHR_xcb_surface", "VK_EXT_headless_surface" };
    const ci = InstanceInfo{ .s_type = 1, .p_next = null, .flags = 0, .app_info = null, .layer_count = 0, .layers = null, .extension_count = extensions.len, .extensions = &extensions };
    var instance: Instance = undefined;
    try std.testing.expectEqual(Result.success, createInstance(&ci, null, &instance));
    var physical_count: u32 = 1;
    var physicals: [1]Physical = undefined;
    try std.testing.expectEqual(Result.success, enumeratePhysicalDevices(instance, &physical_count, &physicals));

    const surface_info = XcbSurfaceCreateInfo{ .s_type = 1_000_005_000, .p_next = null, .flags = 0, .connection = @ptrFromInt(8), .window = 42 };
    var surface: usize = 0;
    try std.testing.expectEqual(Result.success, createXcbSurface(instance, &surface_info, null, &surface));
    try std.testing.expect(surface != 0);

    var supported: u32 = 0;
    try std.testing.expectEqual(Result.success, getSurfaceSupport(physicals[0], 0, surface, &supported));
    try std.testing.expectEqual(@as(u32, 1), supported);
    try std.testing.expectEqual(Result.error_initialization_failed, getSurfaceSupport(physicals[0], 1, surface, &supported));

    var capabilities: SurfaceCapabilities = undefined;
    try std.testing.expectEqual(Result.success, getSurfaceCapabilities(physicals[0], surface, &capabilities));
    try std.testing.expectEqual(@as(u32, 2), capabilities.min_image_count);
    try std.testing.expectEqual(@as(u32, 4), capabilities.max_image_count);
    try std.testing.expectEqual(std.math.maxInt(u32), capabilities.current_extent.width);
