    try std.testing.expectEqual(frame_lifecycle.State.acquired, validSwapchainLocked(swapchain).?.image_states[lifecycle_index]);
    validSemaphoreLocked(foreign_present_semaphore).?.signaled.store(false, .release);
    _ = std.c.pthread_mutex_lock(&validSwapchainLocked(swapchain).?.present_mutex);
    validSwapchainLocked(swapchain).?.image_states[lifecycle_index] = .available;
    _ = std.c.pthread_mutex_unlock(&validSwapchainLocked(swapchain).?.present_mutex);
    test_allocations_before_failure = 0;
    for (0..4096) |_| try std.testing.expectEqual(Result.error_initialization_failed, acquireNextImage(device, swapchain, 0, foreign_acquire_semaphore, 0, &lifecycle_index));
    test_allocations_before_failure = null;
    destroySemaphore(wrong_device, foreign_acquire_semaphore, null);
    destroySemaphore(wrong_device, foreign_present_semaphore, null);
    destroyFence(wrong_device, foreign_acquire_fence, null);
    destroyFence(device, signaled_acquire_fence, null);
    destroyDevice(wrong_device, null);
    destroySwapchain(null, swapchain, null);
    destroySwapchain(device, 0xdead_beef, null);

    destroySemaphore(device, acquired, null);
    destroySemaphore(device, rendered, null);
    destroyFramebuffer(device, attachmentless_framebuffer, null);
    destroyPipeline(device, attachmentless_pipeline[0], null);
    destroyRenderPass(device, attachmentless_render_pass, null);
    destroyFramebuffer(device, multi_framebuffer, null);
    for (multi_pipeline) |pipeline| destroyPipeline(device, pipeline, null);
    destroyRenderPass(device, multi_render_pass, null);
    destroyFramebuffer(device, framebuffer, null);
    destroyImageView(device, view, null);
    destroyImageView(device, depth_view, null);
    destroyImageView(device, texture_view, null);
    destroyImage(device, depth_image, null);
    destroyImage(device, texture_image, null);
    destroyBuffer(device, indirect_buffer, null);
    freeMemory(device, index_memory, null);
    freeMemory(device, indirect_memory, null);
    destroyBuffer(device, uniform_buffer, null);
    // A valid oldSwapchain is retired only after the replacement has been
    // fully created.  Retired objects remain destroyable, but acquisition and
    // presentation must reject them for the rest of their lifetime.
    var replacement_swapchain: usize = 0;
    var replacement_info = swapchain_info;
    replacement_info.old_swapchain = swapchain;
    try std.testing.expectEqual(Result.success, createSwapchain(device, &replacement_info, null, &replacement_swapchain));
    try std.testing.expect(replacement_swapchain != 0 and replacement_swapchain != swapchain);
    try std.testing.expect(validSwapchainLocked(swapchain).?.retiring);
    var retired_index: u32 = 0;
    try std.testing.expectEqual(Result.error_initialization_failed, acquireNextImage(device, swapchain, 0, 0, 0, &retired_index));
    test_allocations_before_failure = 0;
    for (0..4096) |_| try std.testing.expectEqual(Result.error_initialization_failed, acquireNextImage(device, swapchain, 0, 0, 0, &retired_index));
    test_allocations_before_failure = null;
    destroySwapchain(device, replacement_swapchain, null);
    destroySwapchain(device, swapchain, null);
    destroySwapchain(device, timing_swapchain, null);
    destroyCommandPool(device, pool, null);
    destroyPipelineCache(device, graphics_cache, null);
    destroyDevice(device, null);
    try std.testing.expectEqual(Result.error_initialization_failed, queueWaitIdle(queue));
    try std.testing.expectEqual(Result.error_initialization_failed, deviceWaitIdle(device));
    destroyInstance(instance, null);
}

var instance_callback_count: usize = 0;
var device_callback_count: usize = 0;
const callback_dispatch_word: usize = 0xC0DEC0DE;

fn syntheticInstanceLoaderData(instance: Instance, object: *anyopaque) callconv(.c) Result {
    _ = instance;
    const word: *usize = @ptrCast(@alignCast(object));
    word.* = callback_dispatch_word;
    instance_callback_count += 1;
    return .success;
}
fn syntheticDeviceLoaderData(device: Device, object: *anyopaque) callconv(.c) Result {
    _ = device;
    const word: *usize = @ptrCast(@alignCast(object));
    word.* = callback_dispatch_word;
    device_callback_count += 1;
    return .success;
}
var command_callback_calls: usize = 0;
fn commandBufferLoaderData(device: Device, object: *anyopaque) callconv(.c) Result {
    _ = device;
    _ = object;
    command_callback_calls += 1;
    return if (command_callback_calls == 2) .error_initialization_failed else .success;
}
fn failingInstanceLoaderData(instance: Instance, object: *anyopaque) callconv(.c) Result {
    _ = instance;
    _ = object;
    return .error_initialization_failed;
}
fn failingDeviceLoaderData(device: Device, object: *anyopaque) callconv(.c) Result {
    _ = device;
    _ = object;
    return .error_initialization_failed;
}
fn destroyingInstanceLoaderData(instance: Instance, object: *anyopaque) callconv(.c) Result {
    _ = object;
    destroyInstance(instance, null);
    return .success;
}
fn destroyingDeviceLoaderData(device: Device, object: *anyopaque) callconv(.c) Result {
    _ = object;
    destroyDevice(device, null);
    return .success;
}
fn destroyingDecliningDeviceLoaderData(device: Device, object: *anyopaque) callconv(.c) Result {
    _ = object;
    destroyDevice(device, null);
    return .error_initialization_failed;
}

