    try std.testing.expectEqual(Result.success, queueSubmit(queue, 1, @ptrCast(&submit), fence));
    try std.testing.expectEqual(Result.success, waitForFences(device, 1, @ptrCast(&fence), 1, std.math.maxInt(u64)));
