}

fn resetDeadMemorySlotsForAbiTest() !void {
    if (!builtin.is_test) return error.TestUnexpectedResult;
    for (memory_state) |state| try std.testing.expect(state != .live);
    memory_state = [_]SlotState{.never} ** max_memory_objects;
}

fn resetDeadChildSlotsForAbiTest() !void {
    if (!builtin.is_test) return error.TestUnexpectedResult;
    inline for (.{ &image_state, &image_view_state, &framebuffer_state, &render_pass_state, &command_pool_state, &command_buffer_state }) |states| {
        for (states.*) |state| try std.testing.expect(state != .live);
        states.* = [_]SlotState{.never} ** max_child_objects;
    }
}

test "mapped-memory coherency ABI layout and behavior" {
    try resetDeadMemorySlotsForAbiTest();
    try std.testing.expectEqual(@as(usize, 40), @sizeOf(MappedMemoryRange));
    try std.testing.expectEqual(@as(usize, 8), @offsetOf(MappedMemoryRange, "p_next"));
    try std.testing.expectEqual(@as(usize, 16), @offsetOf(MappedMemoryRange, "memory"));
    try std.testing.expectEqual(@as(usize, 24), @offsetOf(MappedMemoryRange, "offset"));

    const ctx = try createTestDeviceContext();
    const allocation = MemoryAllocateInfo{ .s_type = 5, .p_next = null, .allocation_size = 64, .memory_type_index = 0 };
    var memory: usize = 0;
    try std.testing.expectEqual(Result.success, allocateMemory(ctx.device, &allocation, null, &memory));
    var mapped: ?*anyopaque = null;
    try std.testing.expectEqual(Result.success, mapMemory(ctx.device, memory, 0, std.math.maxInt(u64), 0, &mapped));
    const bytes: [*]u8 = @ptrCast(mapped.?);
    @memset(bytes[0..64], 0x5a);

    var ranges = [_]MappedMemoryRange{
        .{ .s_type = 6, .p_next = null, .memory = memory, .offset = 0, .size = 16 },
        .{ .s_type = 6, .p_next = null, .memory = memory, .offset = 16, .size = std.math.maxInt(u64) },
    };
    try std.testing.expectEqual(Result.success, flushMappedMemoryRanges(ctx.device, ranges.len, &ranges));
    try std.testing.expectEqual(Result.success, invalidateMappedMemoryRanges(ctx.device, ranges.len, &ranges));
    for (bytes[0..64]) |byte| try std.testing.expectEqual(@as(u8, 0x5a), byte);
    var commitment: u64 = std.math.maxInt(u64);
    getDeviceMemoryCommitment(ctx.device, memory, &commitment);
    try std.testing.expectEqual(@as(u64, 0), commitment);

    try std.testing.expectEqual(Result.error_initialization_failed, flushMappedMemoryRanges(ctx.device, 0, null));
    try std.testing.expectEqual(Result.error_initialization_failed, invalidateMappedMemoryRanges(ctx.device, max_api_items + 1, &ranges));
    ranges[0].s_type = 5;
    try std.testing.expectEqual(Result.error_initialization_failed, flushMappedMemoryRanges(ctx.device, 1, &ranges));
    ranges[0].s_type = 6;
    ranges[0].p_next = @ptrFromInt(8);
    try std.testing.expectEqual(Result.error_initialization_failed, flushMappedMemoryRanges(ctx.device, 1, &ranges));
    ranges[0].p_next = null;
    ranges[0].size = 0;
    try std.testing.expectEqual(Result.error_initialization_failed, flushMappedMemoryRanges(ctx.device, 1, &ranges));
    ranges[0].size = 2;
    ranges[0].offset = 63;
    try std.testing.expectEqual(Result.error_initialization_failed, flushMappedMemoryRanges(ctx.device, 1, &ranges));
    ranges[0].offset = 64;
    ranges[0].size = std.math.maxInt(u64);
    try std.testing.expectEqual(Result.error_initialization_failed, flushMappedMemoryRanges(ctx.device, 1, &ranges));
    ranges[0].offset = 0;
    ranges[0].size = 64;
    unmapMemory(ctx.device, memory);
    try std.testing.expectEqual(@as(usize, 48), @sizeOf(MemoryMapInfo));
    try std.testing.expectEqual(@as(usize, 32), @sizeOf(MemoryUnmapInfo));
    var mapped2: ?*anyopaque = null;
    const map_info2 = MemoryMapInfo{ .s_type = 1000271000, .p_next = null, .flags = 0, .memory = memory, .offset = 8, .size = 16 };
    try std.testing.expectEqual(Result.success, mapMemory2(ctx.device, &map_info2, &mapped2));
    try std.testing.expect(mapped2 != null);
    const unmap_info2 = MemoryUnmapInfo{ .s_type = 1000271001, .p_next = null, .flags = 0, .memory = memory };
    try std.testing.expectEqual(Result.success, unmapMemory2(ctx.device, &unmap_info2));
    try std.testing.expectEqual(Result.error_initialization_failed, invalidateMappedMemoryRanges(ctx.device, 1, &ranges));

    freeMemory(ctx.device, memory, null);
    destroyDevice(ctx.device, null);
    destroyInstance(ctx.instance, null);
}

test "mapped-memory coherency performance regression is bounded and allocation free" {
    try resetDeadMemorySlotsForAbiTest();
    const ctx = try createTestDeviceContext();
    const allocation = MemoryAllocateInfo{ .s_type = 5, .p_next = null, .allocation_size = 64, .memory_type_index = 0 };
    var memory: usize = 0;
    try std.testing.expectEqual(Result.success, allocateMemory(ctx.device, &allocation, null, &memory));
    var mapped: ?*anyopaque = null;
    try std.testing.expectEqual(Result.success, mapMemory(ctx.device, memory, 0, 64, 0, &mapped));
    var ranges = [_]MappedMemoryRange{.{ .s_type = 6, .p_next = null, .memory = 0, .offset = 0, .size = 64 }} ** max_api_items;
    for (&ranges) |*range| range.memory = memory;

    var inspected: u64 = 0;
    var bytes: u64 = 0;
    {
        lock();
        defer mutex.unlock();
        test_allocations_before_failure = 0;
        defer test_allocations_before_failure = null;
        for (0..1024) |_| {
            const validation = validateMappedMemoryRangesLocked(ctx.device, ranges.len, &ranges) orelse return error.TestUnexpectedResult;
            inspected += validation.ranges;
            bytes += validation.bytes;
        }
    }
    try std.testing.expectEqual(@as(u64, 1024 * max_api_items), inspected);
    try std.testing.expectEqual(@as(u64, 1024 * max_api_items * 64), bytes);
    try std.testing.expect(@as(*MemoryObj, @ptrFromInt(memory)).mapped);

    unmapMemory(ctx.device, memory);
    freeMemory(ctx.device, memory, null);
    destroyDevice(ctx.device, null);
    destroyInstance(ctx.instance, null);
}

test "traditional render passes honor load operations and image layout transitions" {
    try resetDeadChildSlotsForAbiTest();
    const ctx = try createTestDeviceContext();
    const image_info = ImageCreateInfo{ .s_type = 14, .p_next = null, .flags = 0, .image_type = 1, .format = 44, .extent = .{ .width = 2, .height = 2, .depth = 1 }, .mip_levels = 1, .array_layers = 1, .samples = 1, .tiling = 0, .usage = 0x10, .sharing_mode = 0, .queue_family_index_count = 0, .queue_family_indices = null, .initial_layout = 0 };
    var image: usize = 0;
    try std.testing.expectEqual(Result.success, createImage(ctx.device, &image_info, null, &image));
    const allocation = MemoryAllocateInfo{ .s_type = 5, .p_next = null, .allocation_size = 16, .memory_type_index = 0 };
    var memory: usize = 0;
    try std.testing.expectEqual(Result.success, allocateMemory(ctx.device, &allocation, null, &memory));
    try std.testing.expectEqual(Result.success, bindImageMemory(ctx.device, image, memory, 0));
    const view_info = ImageViewCreateInfo{ .s_type = 15, .p_next = null, .flags = 0, .image = image, .view_type = 1, .format = 44, .components = .{ 0, 0, 0, 0 }, .subresource_range = .{ .aspect_mask = 1, .base_mip_level = 0, .level_count = 1, .base_array_layer = 0, .layer_count = 1 } };
    var view: usize = 0;
    try std.testing.expectEqual(Result.success, createImageView(ctx.device, &view_info, null, &view));
    const color_ref = AttachmentReference{ .attachment = 0, .layout = 2 };
    var attachment = AttachmentDescription{ .flags = 0, .format = 44, .samples = 1, .load_op = 0, .store_op = 0, .stencil_load_op = 2, .stencil_store_op = 1, .initial_layout = 0, .final_layout = 1 };
    const subpass = SubpassDescription{ .flags = 0, .pipeline_bind_point = 0, .input_attachment_count = 0, .input_attachments = null, .color_attachment_count = 1, .color_attachments = @ptrCast(@constCast(&color_ref)), .resolve_attachments = null, .depth_stencil_attachment = null, .preserve_attachment_count = 0, .preserve_attachments = null };
    var render_info = RenderPassCreateInfo{ .s_type = 38, .p_next = null, .flags = 0, .attachment_count = 1, .attachments = @ptrCast(&attachment), .subpass_count = 1, .subpasses = @ptrCast(@constCast(&subpass)), .dependency_count = 0, .dependencies = null };
    var render_pass: usize = 0;
    try std.testing.expectEqual(Result.success, createRenderPass(ctx.device, &render_info, null, &render_pass));
    try std.testing.expectEqual(@as(i32, 0), validRenderPassLocked(render_pass).?.color_load_op);
    try std.testing.expectEqual(@as(i32, 0), validRenderPassLocked(render_pass).?.color_initial_layout);
    try std.testing.expectEqual(@as(i32, 2), validRenderPassLocked(render_pass).?.color_subpass_layout);
    try std.testing.expectEqual(@as(i32, 1), validRenderPassLocked(render_pass).?.color_final_layout);
    const framebuffer_info = FramebufferCreateInfo{ .s_type = 37, .p_next = null, .flags = 0, .render_pass = render_pass, .attachment_count = 1, .attachments = @ptrCast(&view), .width = 2, .height = 2, .layers = 1 };
    var framebuffer: usize = 0;
    try std.testing.expectEqual(Result.success, createFramebuffer(ctx.device, &framebuffer_info, null, &framebuffer));
    const pool_info = CommandPoolCreateInfo{ .s_type = 39, .p_next = null, .flags = 2, .queue_family_index = 0 };
    var pool: usize = 0;
    try std.testing.expectEqual(Result.success, createCommandPool(ctx.device, &pool_info, null, &pool));
    const allocate_info = CommandBufferAllocateInfo{ .s_type = 40, .p_next = null, .command_pool = pool, .level = 0, .command_buffer_count = 1 };
    var command: [1]CommandBuffer = undefined;
    try std.testing.expectEqual(Result.success, allocateCommandBuffers(ctx.device, &allocate_info, &command));
    const begin = CommandBufferBeginInfo{ .s_type = 42, .p_next = null, .flags = 0, .inheritance_info = null };
    var render_begin = RenderPassBeginInfo{ .s_type = 43, .p_next = null, .render_pass = render_pass, .framebuffer = framebuffer, .render_area = .{ .offset = .{ .x = 0, .y = 0 }, .extent = .{ .width = 2, .height = 2 } }, .clear_value_count = 0, .clear_values = null };
    const image_object = validImageLocked(image).?;
    std.mem.writeInt(u32, imageBytes(image_object)[0..4], 0xa1b2c3d4, .little);
    try std.testing.expectEqual(Result.success, beginCommandBuffer(command[0], &begin));
    cmdBeginRenderPass(command[0], &render_begin, 0);
    try std.testing.expect(!command[0].impl.invalid);
    try std.testing.expectEqual(@as(u16, 1), command[0].impl.count);
    cmdEndRenderPass(command[0]);
    try std.testing.expect(!command[0].impl.invalid);
    try std.testing.expectEqual(@as(u16, 2), command[0].impl.count);
    try std.testing.expectEqual(Result.success, endCommandBuffer(command[0]));
    const submit = SubmitInfo{ .s_type = 4, .p_next = null, .wait_semaphore_count = 0, .wait_semaphores = null, .wait_dst_stage_mask = null, .command_buffer_count = 1, .command_buffers = &command, .signal_semaphore_count = 0, .signal_semaphores = null };
    try std.testing.expectEqual(Result.success, queueSubmit(ctx.queue, 1, @ptrCast(&submit), 0));
    try std.testing.expectEqual(@as(u32, 0xa1b2c3d4), std.mem.readInt(u32, imageBytes(image_object)[0..4], .little));
    try std.testing.expectEqual(@as(i32, 1), image_object.layout);

    // Vulkan 1.3's promoted store-none operation is also valid for a
    // traditional render pass.  It records a bounded discard at end-of-pass
    // while preserving the bytes until submission executes that discard.
    attachment.store_op = attachment_store_op_none;
    render_info.attachments = @ptrCast(&attachment);
    var none_render_pass: usize = 0;
    try std.testing.expectEqual(Result.success, createRenderPass(ctx.device, &render_info, null, &none_render_pass));
    var none_framebuffer_info = framebuffer_info;
    none_framebuffer_info.render_pass = none_render_pass;
    var none_framebuffer: usize = 0;
    try std.testing.expectEqual(Result.success, createFramebuffer(ctx.device, &none_framebuffer_info, null, &none_framebuffer));
    render_begin.render_pass = none_render_pass;
    render_begin.framebuffer = none_framebuffer;
    render_begin.clear_value_count = 0;
    render_begin.clear_values = null;
    const none_bytes_before = std.mem.readInt(u32, imageBytes(image_object)[0..4], .little);
    try std.testing.expectEqual(Result.success, resetCommandBuffer(command[0], 0));
    try std.testing.expectEqual(Result.success, beginCommandBuffer(command[0], &begin));
    cmdBeginRenderPass(command[0], &render_begin, 0);
    try std.testing.expect(!command[0].impl.invalid);
    cmdEndRenderPass(command[0]);
    try std.testing.expect(!command[0].impl.invalid);
    try std.testing.expectEqual(@as(u16, 3), command[0].impl.count);
    try std.testing.expectEqual(@as(std.meta.Tag(Command), .discard_image), std.meta.activeTag(command[0].impl.commands[1]));
    try std.testing.expectEqual(Result.success, endCommandBuffer(command[0]));
    try std.testing.expectEqual(Result.success, queueSubmit(ctx.queue, 1, @ptrCast(&submit), 0));
    try std.testing.expectEqual(none_bytes_before, std.mem.readInt(u32, imageBytes(image_object)[0..4], .little));
    try std.testing.expect(image_object.force_full_present);
    destroyFramebuffer(ctx.device, none_framebuffer, null);
    destroyRenderPass(ctx.device, none_render_pass, null);
    attachment.store_op = 0;
    render_info.attachments = @ptrCast(&attachment);

    // A CLEAR attachment needs the corresponding indexed clear value.  The
    // rejected begin must not publish a render scope or a command.
    attachment.load_op = 1;
    render_info.attachments = @ptrCast(&attachment);
    var clear_render_pass: usize = 0;
    try std.testing.expectEqual(Result.success, createRenderPass(ctx.device, &render_info, null, &clear_render_pass));
    var clear_framebuffer_info = framebuffer_info;
    clear_framebuffer_info.render_pass = clear_render_pass;
    var clear_framebuffer: usize = 0;
    try std.testing.expectEqual(Result.success, createFramebuffer(ctx.device, &clear_framebuffer_info, null, &clear_framebuffer));
    render_begin.render_pass = clear_render_pass;
    render_begin.framebuffer = clear_framebuffer;
    try std.testing.expectEqual(Result.success, resetCommandBuffer(command[0], 0));
    try std.testing.expectEqual(Result.success, beginCommandBuffer(command[0], &begin));
    cmdBeginRenderPass(command[0], &render_begin, 0);
    try std.testing.expect(command[0].impl.invalid);
    try std.testing.expectEqual(@as(u16, 0), command[0].impl.count);
    try std.testing.expect(command[0].impl.active_render_pass == null);
    var clear_value = ClearValue{ .color = .{ .float32 = .{ 0.25, 0.5, 0.75, 1 } } };
    render_begin.clear_value_count = 1;
    render_begin.clear_values = @ptrCast(&clear_value);
    try std.testing.expectEqual(Result.success, resetCommandBuffer(command[0], 0));
    try std.testing.expectEqual(Result.success, beginCommandBuffer(command[0], &begin));
    cmdBeginRenderPass(command[0], &render_begin, 0);
    try std.testing.expect(!command[0].impl.invalid);
    cmdEndRenderPass(command[0]);
    try std.testing.expectEqual(Result.success, endCommandBuffer(command[0]));
    try std.testing.expectEqual(Result.success, queueSubmit(ctx.queue, 1, @ptrCast(&submit), 0));
    try std.testing.expectEqual(@as(u32, 0xff3f7fbf), std.mem.readInt(u32, imageBytes(image_object)[0..4], .little));
    try std.testing.expectEqual(@as(i32, 1), image_object.layout);

    // Subpass transitions use each subpass's declared attachment layout.  A
    // two-subpass pass therefore records the transition into the second
    // layout before the NEXT_SUBPASS envelope, and the final layout is taken
    // from the subpass that actually ended.
    attachment.load_op = 0;
    attachment.initial_layout = 1;
    attachment.final_layout = 1;
    const multi_refs = [_]AttachmentReference{ .{ .attachment = 0, .layout = 2 }, .{ .attachment = 0, .layout = 1 } };
    const multi_subpasses = [_]SubpassDescription{
        .{ .flags = 0, .pipeline_bind_point = 0, .input_attachment_count = 0, .input_attachments = null, .color_attachment_count = 1, .color_attachments = @ptrCast(@constCast(&multi_refs[0])), .resolve_attachments = null, .depth_stencil_attachment = null, .preserve_attachment_count = 0, .preserve_attachments = null },
        .{ .flags = 0, .pipeline_bind_point = 0, .input_attachment_count = 0, .input_attachments = null, .color_attachment_count = 1, .color_attachments = @ptrCast(@constCast(&multi_refs[1])), .resolve_attachments = null, .depth_stencil_attachment = null, .preserve_attachment_count = 0, .preserve_attachments = null },
    };
    var multi_info = render_info;
    multi_info.subpass_count = 2;
    multi_info.subpasses = @ptrCast(@constCast(&multi_subpasses));
    var multi_render_pass: usize = 0;
    try std.testing.expectEqual(Result.success, createRenderPass(ctx.device, &multi_info, null, &multi_render_pass));
    try std.testing.expectEqual(@as(i32, 2), validRenderPassLocked(multi_render_pass).?.subpass_color_layouts[0]);
    try std.testing.expectEqual(@as(i32, 1), validRenderPassLocked(multi_render_pass).?.subpass_color_layouts[1]);
    var multi_framebuffer_info = framebuffer_info;
    multi_framebuffer_info.render_pass = multi_render_pass;
    var multi_framebuffer: usize = 0;
    try std.testing.expectEqual(Result.success, createFramebuffer(ctx.device, &multi_framebuffer_info, null, &multi_framebuffer));
    render_begin.render_pass = multi_render_pass;
    render_begin.framebuffer = multi_framebuffer;
    render_begin.clear_value_count = 0;
    render_begin.clear_values = null;
    try std.testing.expectEqual(Result.success, resetCommandBuffer(command[0], 0));
    try std.testing.expectEqual(Result.success, beginCommandBuffer(command[0], &begin));
    cmdBeginRenderPass(command[0], &render_begin, 0);
    try std.testing.expect(!command[0].impl.invalid);
    try std.testing.expectEqual(@as(u16, 1), command[0].impl.count);
    cmdNextSubpass(command[0], 0);
    try std.testing.expect(!command[0].impl.invalid);
    try std.testing.expectEqual(@as(u16, 3), command[0].impl.count);
    cmdEndRenderPass(command[0]);
    try std.testing.expect(!command[0].impl.invalid);
    try std.testing.expectEqual(@as(u16, 3), command[0].impl.count);
    try std.testing.expectEqual(Result.success, endCommandBuffer(command[0]));
    try std.testing.expectEqual(Result.success, queueSubmit(ctx.queue, 1, @ptrCast(&submit), 0));
    try std.testing.expectEqual(@as(i32, 1), image_object.layout);

    // The warm begin/end path carries transitions but must remain allocation
    // free.  UNDEFINED initial layout accepts the tracked final layout as the
    // previous state and still transitions through the declared subpass.
    test_allocations_before_failure = 0;
    defer test_allocations_before_failure = null;
    for (0..4096) |_| {
        try std.testing.expectEqual(Result.success, resetCommandBuffer(command[0], 0));
        try std.testing.expectEqual(Result.success, beginCommandBuffer(command[0], &begin));
        cmdBeginRenderPass(command[0], &render_begin, 0);
        cmdNextSubpass(command[0], 0);
        cmdEndRenderPass(command[0]);
        try std.testing.expect(!command[0].impl.invalid);
    }
    test_allocations_before_failure = null;
    freeCommandBuffers(ctx.device, pool, 1, &command);
    destroyCommandPool(ctx.device, pool, null);
    destroyFramebuffer(ctx.device, multi_framebuffer, null);
    destroyRenderPass(ctx.device, multi_render_pass, null);
    destroyFramebuffer(ctx.device, clear_framebuffer, null);
    destroyFramebuffer(ctx.device, framebuffer, null);
    destroyRenderPass(ctx.device, clear_render_pass, null);
    destroyRenderPass(ctx.device, render_pass, null);
    destroyImageView(ctx.device, view, null);
    destroyImage(ctx.device, image, null);
    freeMemory(ctx.device, memory, null);
    destroyDevice(ctx.device, null);
    destroyInstance(ctx.instance, null);
}

test "traditional depth-only render passes bind, clear, transition, and stay allocation free" {
    try resetDeadChildSlotsForAbiTest();
    const ctx = try createTestDeviceContext();
    const image_info = ImageCreateInfo{ .s_type = 14, .p_next = null, .flags = 0, .image_type = 1, .format = 126, .extent = .{ .width = 2, .height = 2, .depth = 1 }, .mip_levels = 1, .array_layers = 1, .samples = 1, .tiling = 0, .usage = 0x20, .sharing_mode = 0, .queue_family_index_count = 0, .queue_family_indices = null, .initial_layout = 0 };
    var image: usize = 0;
    try std.testing.expectEqual(Result.success, createImage(ctx.device, &image_info, null, &image));
    const allocation = MemoryAllocateInfo{ .s_type = 5, .p_next = null, .allocation_size = 16, .memory_type_index = 0 };
    var memory: usize = 0;
    try std.testing.expectEqual(Result.success, allocateMemory(ctx.device, &allocation, null, &memory));
    try std.testing.expectEqual(Result.success, bindImageMemory(ctx.device, image, memory, 0));
    const view_info = ImageViewCreateInfo{ .s_type = 15, .p_next = null, .flags = 0, .image = image, .view_type = 1, .format = 126, .components = .{ 0, 0, 0, 0 }, .subresource_range = .{ .aspect_mask = 2, .base_mip_level = 0, .level_count = 1, .base_array_layer = 0, .layer_count = 1 } };
    var view: usize = 0;
    try std.testing.expectEqual(Result.success, createImageView(ctx.device, &view_info, null, &view));
    const depth_ref = AttachmentReference{ .attachment = 0, .layout = 3 };
    const attachment = AttachmentDescription{ .flags = 0, .format = 126, .samples = 1, .load_op = 1, .store_op = 1, .stencil_load_op = 2, .stencil_store_op = 1, .initial_layout = 0, .final_layout = 3 };
    const subpass = SubpassDescription{ .flags = 0, .pipeline_bind_point = 0, .input_attachment_count = 0, .input_attachments = null, .color_attachment_count = 0, .color_attachments = null, .resolve_attachments = null, .depth_stencil_attachment = @ptrCast(&depth_ref), .preserve_attachment_count = 0, .preserve_attachments = null };
    const render_info = RenderPassCreateInfo{ .s_type = 38, .p_next = null, .flags = 0, .attachment_count = 1, .attachments = @ptrCast(&attachment), .subpass_count = 1, .subpasses = @ptrCast(&subpass), .dependency_count = 0, .dependencies = null };
    var render_pass: usize = 0;
    try std.testing.expectEqual(Result.success, createRenderPass(ctx.device, &render_info, null, &render_pass));
    const pass = validRenderPassLocked(render_pass).?;
    try std.testing.expect(pass.framebuffer_supported);
    try std.testing.expectEqual(@as(u32, 1), pass.framebuffer_attachment_count);
    try std.testing.expectEqual(AttachmentRole.depth, pass.framebuffer_attachments[0].role);
    try std.testing.expectEqual(@as(i32, 3), pass.subpass_depth_layouts[0]);
    const framebuffer_info = FramebufferCreateInfo{ .s_type = 37, .p_next = null, .flags = 0, .render_pass = render_pass, .attachment_count = 1, .attachments = @ptrCast(&view), .width = 2, .height = 2, .layers = 1 };
    var framebuffer: usize = 0;
    try std.testing.expectEqual(Result.success, createFramebuffer(ctx.device, &framebuffer_info, null, &framebuffer));
    try std.testing.expect(validFramebufferLocked(framebuffer).?.color_image == null);
    try std.testing.expect(validFramebufferLocked(framebuffer).?.depth_image != null);

    const pool_info = CommandPoolCreateInfo{ .s_type = 39, .p_next = null, .flags = 2, .queue_family_index = 0 };
    var pool: usize = 0;
    try std.testing.expectEqual(Result.success, createCommandPool(ctx.device, &pool_info, null, &pool));
    const allocate_info = CommandBufferAllocateInfo{ .s_type = 40, .p_next = null, .command_pool = pool, .level = 0, .command_buffer_count = 1 };
    var command: [1]CommandBuffer = undefined;
    try std.testing.expectEqual(Result.success, allocateCommandBuffers(ctx.device, &allocate_info, &command));
    const begin = CommandBufferBeginInfo{ .s_type = 42, .p_next = null, .flags = 0, .inheritance_info = null };
    var depth_clear = ClearValue{ .depth_stencil = .{ .depth = 0.25, .stencil = 0 } };
    var render_begin = RenderPassBeginInfo{ .s_type = 43, .p_next = null, .render_pass = render_pass, .framebuffer = framebuffer, .render_area = .{ .offset = .{ .x = 0, .y = 0 }, .extent = .{ .width = 2, .height = 2 } }, .clear_value_count = 1, .clear_values = @ptrCast(&depth_clear) };
    try std.testing.expectEqual(Result.success, beginCommandBuffer(command[0], &begin));
    cmdBeginRenderPass(command[0], &render_begin, 0);
    try std.testing.expect(!command[0].impl.invalid);
    try std.testing.expectEqual(@as(u16, 2), command[0].impl.count);
    try std.testing.expectEqual(@as(std.meta.Tag(Command), .clear_depth), std.meta.activeTag(command[0].impl.commands[1]));
    cmdEndRenderPass(command[0]);
    try std.testing.expect(!command[0].impl.invalid);
    try std.testing.expectEqual(Result.success, endCommandBuffer(command[0]));
    const submit = SubmitInfo{ .s_type = 4, .p_next = null, .wait_semaphore_count = 0, .wait_semaphores = null, .wait_dst_stage_mask = null, .command_buffer_count = 1, .command_buffers = &command, .signal_semaphore_count = 0, .signal_semaphores = null };
    try std.testing.expectEqual(Result.success, queueSubmit(ctx.queue, 1, @ptrCast(&submit), 0));
    const image_object = validImageLocked(image).?;
    try std.testing.expectEqual(@as(u32, 0x3e80_0000), std.mem.readInt(u32, imageBytes(image_object)[0..4], .little));
    try std.testing.expectEqual(@as(i32, 3), image_object.layout);

    // The same attachment-role model also supports depth-only subpass
    // transitions; no color image is required while advancing the scope.
    const second_depth_ref = AttachmentReference{ .attachment = 0, .layout = 1 };
    const depth_subpasses = [_]SubpassDescription{
        subpass,
        .{ .flags = 0, .pipeline_bind_point = 0, .input_attachment_count = 0, .input_attachments = null, .color_attachment_count = 0, .color_attachments = null, .resolve_attachments = null, .depth_stencil_attachment = @ptrCast(&second_depth_ref), .preserve_attachment_count = 0, .preserve_attachments = null },
    };
    var depth_multi_info = render_info;
    depth_multi_info.subpass_count = depth_subpasses.len;
    depth_multi_info.subpasses = @ptrCast(&depth_subpasses);
    var depth_multi_pass: usize = 0;
    try std.testing.expectEqual(Result.success, createRenderPass(ctx.device, &depth_multi_info, null, &depth_multi_pass));
    var depth_multi_framebuffer_info = framebuffer_info;
    depth_multi_framebuffer_info.render_pass = depth_multi_pass;
    var depth_multi_framebuffer: usize = 0;
    try std.testing.expectEqual(Result.success, createFramebuffer(ctx.device, &depth_multi_framebuffer_info, null, &depth_multi_framebuffer));
    render_begin.render_pass = depth_multi_pass;
    render_begin.framebuffer = depth_multi_framebuffer;
    try std.testing.expectEqual(Result.success, resetCommandBuffer(command[0], 0));
    try std.testing.expectEqual(Result.success, beginCommandBuffer(command[0], &begin));
    cmdBeginRenderPass(command[0], &render_begin, 0);
    try std.testing.expect(!command[0].impl.invalid);
    cmdNextSubpass(command[0], 0);
    try std.testing.expect(!command[0].impl.invalid);
    cmdEndRenderPass(command[0]);
    try std.testing.expect(!command[0].impl.invalid);
    try std.testing.expectEqual(@as(u16, 4), command[0].impl.count);
    try std.testing.expectEqual(Result.success, endCommandBuffer(command[0]));
    try std.testing.expectEqual(Result.success, queueSubmit(ctx.queue, 1, @ptrCast(&submit), 0));
    try std.testing.expectEqual(@as(i32, 3), image_object.layout);
    destroyFramebuffer(ctx.device, depth_multi_framebuffer, null);
    destroyRenderPass(ctx.device, depth_multi_pass, null);

    // Missing the depth clear value is rejected atomically at record time.
    render_begin.render_pass = render_pass;
    render_begin.framebuffer = framebuffer;
    render_begin.clear_value_count = 0;
    render_begin.clear_values = null;
    try std.testing.expectEqual(Result.success, resetCommandBuffer(command[0], 0));
    try std.testing.expectEqual(Result.success, beginCommandBuffer(command[0], &begin));
    cmdBeginRenderPass(command[0], &render_begin, 0);
    try std.testing.expect(command[0].impl.invalid);
    try std.testing.expectEqual(@as(u16, 0), command[0].impl.count);
    try std.testing.expect(command[0].impl.active_render_pass == null);

    // Warm begin/end remains allocation free and preserves the depth-only
    // attachment identity across command-buffer reuse.
    render_begin.clear_value_count = 1;
    render_begin.clear_values = @ptrCast(&depth_clear);
    test_allocations_before_failure = 0;
    defer test_allocations_before_failure = null;
    for (0..4096) |_| {
        try std.testing.expectEqual(Result.success, resetCommandBuffer(command[0], 0));
        try std.testing.expectEqual(Result.success, beginCommandBuffer(command[0], &begin));
        cmdBeginRenderPass(command[0], &render_begin, 0);
        cmdEndRenderPass(command[0]);
        try std.testing.expect(!command[0].impl.invalid);
    }

    freeCommandBuffers(ctx.device, pool, 1, &command);
    destroyCommandPool(ctx.device, pool, null);
    destroyFramebuffer(ctx.device, framebuffer, null);
    destroyRenderPass(ctx.device, render_pass, null);
    destroyImageView(ctx.device, view, null);
    destroyImage(ctx.device, image, null);
    freeMemory(ctx.device, memory, null);
    destroyDevice(ctx.device, null);
    destroyInstance(ctx.instance, null);
}

test "traditional attachmentless render passes support discard scopes allocation free" {
    try resetDeadChildSlotsForAbiTest();
    const ctx = try createTestDeviceContext();
    const subpass = SubpassDescription{ .flags = 0, .pipeline_bind_point = 0, .input_attachment_count = 0, .input_attachments = null, .color_attachment_count = 0, .color_attachments = null, .resolve_attachments = null, .depth_stencil_attachment = null, .preserve_attachment_count = 0, .preserve_attachments = null };
    const render_info = RenderPassCreateInfo{ .s_type = 38, .p_next = null, .flags = 0, .attachment_count = 0, .attachments = null, .subpass_count = 1, .subpasses = @ptrCast(&subpass), .dependency_count = 0, .dependencies = null };
    var render_pass: usize = 0;
    try std.testing.expectEqual(Result.success, createRenderPass(ctx.device, &render_info, null, &render_pass));
    const pass = validRenderPassLocked(render_pass).?;
    try std.testing.expect(pass.framebuffer_supported);
    try std.testing.expectEqual(@as(u32, 0), pass.framebuffer_attachment_count);
    const framebuffer_info = FramebufferCreateInfo{ .s_type = 37, .p_next = null, .flags = 0, .render_pass = render_pass, .attachment_count = 0, .attachments = null, .width = 4, .height = 3, .layers = 1 };
    var framebuffer: usize = 0;
    try std.testing.expectEqual(Result.success, createFramebuffer(ctx.device, &framebuffer_info, null, &framebuffer));
    const framebuffer_object = validFramebufferLocked(framebuffer).?;
    try std.testing.expect(framebuffer_object.color_image == null and framebuffer_object.depth_image == null);
    try std.testing.expectEqual(@as(u32, 4), framebuffer_object.width);
    try std.testing.expectEqual(@as(u32, 3), framebuffer_object.height);

    const pool_info = CommandPoolCreateInfo{ .s_type = 39, .p_next = null, .flags = 2, .queue_family_index = 0 };
    var pool: usize = 0;
    try std.testing.expectEqual(Result.success, createCommandPool(ctx.device, &pool_info, null, &pool));
    const allocate_info = CommandBufferAllocateInfo{ .s_type = 40, .p_next = null, .command_pool = pool, .level = 0, .command_buffer_count = 1 };
    var command: [1]CommandBuffer = undefined;
    try std.testing.expectEqual(Result.success, allocateCommandBuffers(ctx.device, &allocate_info, &command));
    const begin = CommandBufferBeginInfo{ .s_type = 42, .p_next = null, .flags = 0, .inheritance_info = null };
    var render_begin = RenderPassBeginInfo{ .s_type = 43, .p_next = null, .render_pass = render_pass, .framebuffer = framebuffer, .render_area = .{ .offset = .{ .x = 0, .y = 0 }, .extent = .{ .width = 4, .height = 3 } }, .clear_value_count = 0, .clear_values = null };
    try std.testing.expectEqual(Result.success, beginCommandBuffer(command[0], &begin));
    cmdBeginRenderPass(command[0], &render_begin, 0);
    try std.testing.expect(!command[0].impl.invalid);
    try std.testing.expectEqual(@as(u16, 0), command[0].impl.count);
    cmdEndRenderPass(command[0]);
    try std.testing.expect(!command[0].impl.invalid);
    try std.testing.expectEqual(Result.success, endCommandBuffer(command[0]));
    const submit = SubmitInfo{ .s_type = 4, .p_next = null, .wait_semaphore_count = 0, .wait_semaphores = null, .wait_dst_stage_mask = null, .command_buffer_count = 1, .command_buffers = &command, .signal_semaphore_count = 0, .signal_semaphores = null };
    try std.testing.expectEqual(Result.success, queueSubmit(ctx.queue, 1, @ptrCast(&submit), 0));

    // The framebuffer extent is the only bounds source when no image exists.
    // Reject an oversized render area without publishing any scope or command.
    render_begin.render_area.extent = .{ .width = 5, .height = 3 };
    try std.testing.expectEqual(Result.success, resetCommandBuffer(command[0], 0));
    try std.testing.expectEqual(Result.success, beginCommandBuffer(command[0], &begin));
    cmdBeginRenderPass(command[0], &render_begin, 0);
    try std.testing.expect(command[0].impl.invalid);
    try std.testing.expectEqual(@as(u16, 0), command[0].impl.count);
    try std.testing.expect(command[0].impl.active_render_pass == null);

    // Multiple attachmentless subpasses remain a valid discard-only scope;
    // advancing records only the bounded NEXT_SUBPASS envelope.
    const subpasses = [_]SubpassDescription{ subpass, subpass };
    var multi_info = render_info;
    multi_info.subpass_count = subpasses.len;
    multi_info.subpasses = @ptrCast(&subpasses);
    var multi_render_pass: usize = 0;
    try std.testing.expectEqual(Result.success, createRenderPass(ctx.device, &multi_info, null, &multi_render_pass));
    var multi_framebuffer_info = framebuffer_info;
    multi_framebuffer_info.render_pass = multi_render_pass;
    var multi_framebuffer: usize = 0;
    try std.testing.expectEqual(Result.success, createFramebuffer(ctx.device, &multi_framebuffer_info, null, &multi_framebuffer));
    render_begin.render_pass = multi_render_pass;
    render_begin.framebuffer = multi_framebuffer;
    render_begin.render_area.extent = .{ .width = 4, .height = 3 };
    try std.testing.expectEqual(Result.success, resetCommandBuffer(command[0], 0));
    try std.testing.expectEqual(Result.success, beginCommandBuffer(command[0], &begin));
    cmdBeginRenderPass(command[0], &render_begin, 0);
    cmdNextSubpass(command[0], 0);
    try std.testing.expect(!command[0].impl.invalid);
    try std.testing.expectEqual(@as(u16, 1), command[0].impl.count);
    try std.testing.expectEqual(@as(std.meta.Tag(Command), .next_subpass), std.meta.activeTag(command[0].impl.commands[0]));
    cmdEndRenderPass(command[0]);
    try std.testing.expect(!command[0].impl.invalid);
    try std.testing.expectEqual(Result.success, endCommandBuffer(command[0]));
    try std.testing.expectEqual(Result.success, queueSubmit(ctx.queue, 1, @ptrCast(&submit), 0));

    // Once warmed, a no-target begin/end must not allocate, matching the
    // allocation-free dynamic attachmentless path.
    render_begin.render_pass = render_pass;
    render_begin.framebuffer = framebuffer;
    test_allocations_before_failure = 0;
    defer test_allocations_before_failure = null;
    for (0..4096) |_| {
        try std.testing.expectEqual(Result.success, resetCommandBuffer(command[0], 0));
        try std.testing.expectEqual(Result.success, beginCommandBuffer(command[0], &begin));
        cmdBeginRenderPass(command[0], &render_begin, 0);
        cmdEndRenderPass(command[0]);
        try std.testing.expect(!command[0].impl.invalid);
    }
    test_allocations_before_failure = null;
    freeCommandBuffers(ctx.device, pool, 1, &command);
    destroyCommandPool(ctx.device, pool, null);
    destroyFramebuffer(ctx.device, multi_framebuffer, null);
    destroyRenderPass(ctx.device, multi_render_pass, null);
    destroyFramebuffer(ctx.device, framebuffer, null);
    destroyRenderPass(ctx.device, render_pass, null);
    destroyDevice(ctx.device, null);
    destroyInstance(ctx.instance, null);
}

test "explicit behavioral requirement matrix is complete" {
    const fields = @typeInfo(Requirement).@"enum".fields;
    inline for (fields) |field| {
        const mask = @as(u64, 1) << field.value;
        try std.testing.expect(requirement_hits & mask != 0);
    }
}

test "pinned Vulkan 1.4 core command inventory resolves through the ICD dispatch" {
    try std.testing.expectEqual(@as(usize, 234), core_command_inventory.names.len);
    for (core_command_inventory.names) |command| {
        try std.testing.expect(instanceLookup(command) != null);
    }
    // Warm lookup is intentionally allocation-free and bounded for every entry.
    for (0..4096) |_| for (core_command_inventory.names) |command| try std.testing.expect(instanceLookup(command) != null);
}

test "pinned core command inventory is deterministic and duplicate-free" {
    for (core_command_inventory.names[1..], 1..) |command, index| {
        try std.testing.expect(std.mem.lessThan(u8, core_command_inventory.names[index - 1], command));
    }
}
